/* İcat Defteri — Synchronized 7-Language Documentation Data & Renderer */
(function () {
  'use strict';
  var GUIDE = {"tr":{"badge":"Resmî Kullanım Kılavuzu","title":"İcat Defteri — Kullanım Kılavuzu","meta":"Son Güncelleme: 21 Kasım 2026 • 18 Bölüm • 7 Dil Desteği","sections":[["1. İlk Kurulum, Dil Seçimi ve İzinler","İcat Defteri açıldığında telefonunuzun dilini otomatik algılar. Türkçe, İngilizce, Almanca, Fransızca, İspanyolca, İtalyanca ve Portekizce olmak üzere <strong>7 dil</strong> tam desteklenir. Menü › <strong>Dil Seç</strong> adımından istediğiniz zaman değiştirebilirsiniz.<br>• <strong>Mikrofon İzni (RECORD_AUDIO):</strong> Yalnızca sesle yazma veya .m4a ses kaydı başlattığınızda istenir; uygulama arka planda dinleme yapmaz.<br>• <strong>Bildirim İzni (POST_NOTIFICATIONS):</strong> Hatırlatıcıları zamanında göstermek içindir.<br>• <strong>Kamera:</strong> Yalnızca nota doğrudan fotoğraf çekmek istediğinizde Android sistem kamerasını açar."],["2. Başlıklar, Neon Kenarlar ve Not Oluşturma","Ana ekranda sağ alttaki <strong>+</strong> butonundan yeni başlık (ör. Projelerim, Fikirler) açabilirsiniz. Her yeni başlık 7 renkli neon sol kenar vurgusuyla ayrışır; mevcut V1 başlık renkleriniz korunur. Başlık içindeki <strong>+</strong> butonunda üç bağımsız seçenek vardır: <strong>Metin Not</strong> (klavye), <strong>Sesle Yaz</strong> (canlı dikte) ve <strong>Ses Kaydet</strong> (gerçek M4A kayıt)."],["3. Sesle Yazma (Dikte) ve Gerçek M4A Ses Kaydı Farkı","<ul><li><strong>Sesle Yaz (Dikte):</strong> Android/Google Konuşma Hizmetleri ile konuşmanızı anlık metne çevirir. Ham ses kaydedilmez; yalnızca metin tutulur. Kayıt sırasında <em>\"Nokta\" (.), \"Virgül\" (,), \"Soru işareti\" (?), \"Ünlem\" (!), \"Yeni satır\"</em> gibi sesli noktalama komutlarını kullanabilirsiniz.</li><li><strong>Ses Kaydet (.m4a):</strong> Gerçek 44.1 kHz AAC (.m4a) ses dosyası kaydeder. Bu dosyalar telefonun genel Müzik/Medya klasörüne değil, uygulamaya özel güvenli Android dahili alanına (<code>files/recordings/</code>) kaydedilir.</li><li><strong>Korumalı Kayıt:</strong> Uygulama kaldırılırsa veya cihaz sıfırlanırsa bu dahili kayıtlar silinir. Bir kaydı dışarı aktarmak için karttan <strong>Paylaş</strong> diyebilirsiniz (bu işlem seçilen uygulamaya ayrı bir kopya gönderir).</li></ul>"],["4. Not Etiketleri ve Etiketlere Göre Filtreleme","Notlara <strong>#</strong> butonu ile <code>#önemli</code>, <code>#fikir</code> gibi etiketler ekleyebilir veya kendi özel etiketlerinizi oluşturabilirsiniz. Üst menüdeki <strong>Huni (Filtre) › Etikete Göre Filtrele</strong> seçeneğiyle tek veya birden fazla etikete sahip notları başlıklar arasında anında süzebilirsiniz. Silinen bir etiket sistemden kalıcı olarak çıkarılır ve eski etiketler kendiliğinden geri gelmez."],["5. Başlık ve Notlarda Genel Arama","Ana ekrandaki arama simgesi tüm başlıklarda ve not metinlerinde anlık arama yapar (Türkçe büyük/küçük <strong>İ/ı/Ö/Ü</strong> ayrımına uyumludur). Çöp kutusundaki silinmiş kayıtlar arama sonuçlarına karıştırılmaz; dokunduğunuz sonuç sizi doğrudan ilgili not veya başlığa götürür."],["6. Android Ana Ekran Widget'ı","Telefonunuzun ana ekranından widget ekleyerek uygulamayı açmadan tek dokunuşla <strong>Sesli Not Dikte</strong> ekranını başlatabilirsiniz. Uygulamada <strong>Cihaz Kilidi</strong> açıksa widget dikteyi başlatmadan önce parmak izi/PIN/desen doğrulaması ister; böylece fikirleriniz kilit ekranı arkasında korunur."],["7. Profesyonel PDF Proje / Fikir Raporu","Herhangi bir başlığın sağ üst veya üç nokta menüsünden <strong>PDF Raporu Oluştur</strong> diyerek başlık adı, oluşturulma tarihi, tüm notlar, etiketler, ses/ek özetleri ve görselleri içeren düzenli A4 PDF belgesi üretebilir, cihazınıza kaydedebilir veya paylaşabilirsiniz."],["8. Cihaza ve Google Drive'a Manuel Yedekleme","<ul><li><strong>Hızlı Metin Yedeği (.json):</strong> <em>Cihaza Yedekle › Yedekle / Dışa Aktar</em> bölümünde notlarınızı, başlıklarınızı, etiketlerinizi ve hatırlatıcı tanımlarınızı hafif bir <code>.json</code> dosyası olarak kaydeder; ses, fotoğraf ve videoları içermez.</li><li><strong>Tam Yedek (.zip):</strong> <em>Cihaza Yedekle</em> bölümünde notlarınızla birlikte fotoğraf, video, ses kayıtları ve dosya eklerinizi şifresiz <code>.zip</code> arşivi olarak kaydeder (<em>Medya dosyalarını dahil et</em> kutusu başlangıçta işaretlidir; kapatılırsa yalnızca metin ve not yapısı arşivlenir).</li><li><strong>Google Drive Yedekle (İsteğe Bağlı / Şifresiz ZIP):</strong> Kendi Google hesabınızı <code>drive.file</code> yetkisiyle bağlayarak <strong>Drive'ım › İcat Defteri › Yedekler</strong> klasörüne medyasız veya medyalı olarak yalnızca <strong>şifresiz ZIP</strong> formatında manuel yedek alabilir ve geri yükleyebilirsiniz. <em>Medya dosyalarını dahil et</em> kutusu Drive tarafında varsayılan olarak kapalıdır.</li><li><strong>Şifreleme Bilgisi:</strong> Yerel (.json / .zip) ve Google Drive (.zip) yedekleri İcat Defteri tarafından ayrıca parola ile şifrelenmez.</li><li><strong>Geri Yükleme:</strong> Kaydettiğiniz yerel yedekleri <em>Menü › Cihaza Yedekle › Yedeği Yükle / İçe Aktar</em> bölümünden, Drive yedeklerini ise Google Drive ekranından <em>Birleştir (Güvenli)</em> veya onaylı <em>Üzerine Yaz</em> seçeneğiyle geri yükleyebilirsiniz.</li></ul>"],["9. Beş Tema Seçeneği","Sol menüden <strong>Tema Seç</strong> penceresini açarak <strong>Koyu Neon</strong>, <strong>Açık</strong>, <strong>Saf AMOLED</strong>, <strong>Gece Yarısı (Midnight)</strong> ve <strong>Grafit</strong> görünümlerinden dilediğinizi seçebilirsiniz. Sistem durum çubuğu renkleri seçilen temaya otomatik uyarlanır."],["10. Sürükle-Bırak Manuel Sıralama","Filtre/Sıralama menüsünden <strong>Manuel Sıralama</strong> seçildiğinde başlıkların ve notların sağında tutamaçlar görünür. Kartları sürükleyip bırakarak kendi öncelik sıranızı belirleyebilirsiniz; düzeniniz otomatik kaydedilir."],["11. Görsel, Fotoğraf, Video, Belge ve Çizim Ekleme","Not detayından veya ataş simgesinden galeri görseli, video, PDF/belge (tek dosya sınırı <strong>200 MB</strong>), kamera fotoğrafı veya el çizimi ekleyebilirsiniz. Seçtiğiniz harici dosyalar <code>files/attachments/</code> altına <strong>bağımsız bir kopya</strong> olarak aktarılır. Bu sayede sonradan telefon galerisinden veya İndirilenler klasöründen kaynak dosyayı silseniz bile notunuzdaki kopya korunur."],["12. Çizim Tahtası ve Tam Ekran Büyütme","Eskiz penceresinin sağ üstündeki büyütme simgesine basarak tuvali <strong>tam ekran</strong> yapabilirsiniz. Çizimler vektör koordinatlarıyla saklandığından tam ekrana geçerken, normal boyuta dönerken veya ekran yönü değişirken çizimleriniz kaybolmaz. Tam ekrandayken Android donanım <strong>Geri</strong> tuşuna bir kez basmak çizimi kaybetmeden pencereyi normal boyuta küçültür."],["13. Hatırlatıcılar, Takvim ve Sesli Okuma (TTS)","<ul><li><strong>Hatırlatıcılar:</strong> Tek seferlik, günlük, haftalık veya aylık alarmlar kurabilir, Menü › <strong>Takvim</strong> ekranından tümünü yönetebilirsiniz. Not: Bazı telefonlarda aşırı pil kısıtlaması alarmları geciktirebilir; kritik hatırlatmalar için İcat Defteri'ni pil optimizasyonundan hariç tutmanız önerilir.</li><li><strong>Sesli Okuma:</strong> Not detayındaki hoparlör düğmesi notunuzu cihazın yerel TTS motoruyla sesli okur.</li></ul>"],["14. Biyometrik / Cihaz Kilidi","Menüden <strong>Uygulama Kilidi</strong>ni açtığınızda cihazınızdaki parmak izi, yüz tanıma, PIN veya desen koruması kullanılır. Uygulama kendi ayrı bir şifreyi veya biyometrik veriyi sunucularında saklamaz."],["15. Çöp Kutusu, Geri Yükleme ve Kalıcı Silme","Silinen not ve başlıklar hemen yok olmaz; <strong>30 gün boyunca Çöp Kutusu'nda</strong> bekletilir. Bu sürede notla birlikte M4A ses kaydı ve dosya ekleri de geri getirilebilir şekilde korunur. <strong>Kalıcı Sil</strong> yaptığınızda veya 30 gün dolduğunda uygulamaya özel <code>files/recordings/</code> ve <code>files/attachments/</code> kopyaları cihazdan kalıcı olarak silinir (telefonunuzdaki orijinal galeri dosyalarına dokunulmaz)."],["16. Telefon Değiştirme ve Veri Taşıma","<ul><li><strong>Yalnızca Notlar İçin:</strong> Eski cihazda <em>Hızlı Metin Yedeği (.json)</em> veya medyasız ZIP/Drive yedeği alıp yeni cihazda <strong>Yedeği Yükle / İçe Aktar</strong> ile geri yükleyin. Notlar açılır ancak M4A ses kayıtları ve dosya ekleri yeni telefona taşınmadığı için \"bulunamadı / eksik\" olarak görünür.</li><li><strong>Tüm Ses ve Eklerle Taşımak İçin:</strong> <em>Cihaza Yedekle › Tam Yedek</em> veya <em>Google Drive Yedekle</em> bölümünde <strong>Medya dosyalarını dahil et</strong> seçeneğini açık tutarak <code>.zip</code> tam yedeği alın ve yeni telefonda geri yükleyin.</li></ul>"],["17. Veri Kaybını Önleme Önerileri","Yalnızca telefonun kendi hafızasında tutulan yedekler, cihaz kaybolduğunda, sıfırlandığında veya uygulama silindiğinde birlikte yok olabilir. Önemli buluş ve notlarınız için doğrulanmış bir <code>.json</code> veya <code>.zip</code> yedeğini mutlaka telefon dışında (kişisel Google Drive hesabınız, e-posta veya harici bilgisayar/disk) saklayın."],["18. Sık Sorulan Sorular ve Destek","<ul><li><strong>Ses kayıtlarım Müzik uygulamasında neden yok?</strong> Gizliliğiniz için M4A kayıtlar dışa açık klasöre değil, uygulama içi özel <code>files/recordings/</code> alanına yazılır.</li><li><strong>Drive bağlantısını kesersem yedeklerim silinir mi?</strong> Hayır. Bağlantıyı kesmek yalnızca uygulamadaki oturum anahtarını temizler; Drive'daki dosyalar siz Drive üzerinden silmedikçe hesabınızda kalır.</li><li><strong>İletişim:</strong> Geliştirici Ramazan Kocatürk — <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></li></ul>"]]},"en":{"badge":"Official User Guide","title":"İcat Defteri — User Guide","meta":"Last Updated: November 21, 2026 • 18 Sections • 7 Languages","sections":[["1. Initial Setup, Language Selection & Permissions","İcat Defteri detects your device language at first launch and supports <strong>7 languages</strong> (Turkish, English, German, French, Spanish, Italian, Portuguese). Switch anytime via Menu › <strong>Change Language</strong>.<br>• <strong>Microphone (RECORD_AUDIO):</strong> Used only while dictating or recording .m4a audio.<br>• <strong>Notifications (POST_NOTIFICATIONS):</strong> Displays scheduled reminders on time.<br>• <strong>Camera:</strong> Opens the system camera only when attaching a new photo."],["2. Titles, Neon Edge Colors & Notes","Tap <strong>+</strong> to create titles distinguished by 7 neon left-border accents while preserving V1 text colors. Inside any title, <strong>+</strong> offers three independent actions: <strong>Text Note</strong>, <strong>Voice Dictation</strong>, and <strong>Record Audio (.m4a)</strong>."],["3. Voice Dictation vs. Real M4A Audio Recording","<ul><li><strong>Voice Dictation:</strong> Converts speech into text via Android/Google Speech Services without saving raw audio.</li><li><strong>M4A Audio Recording:</strong> Records real AAC <code>.m4a</code> audio inside app-private storage (<code>files/recordings/</code>), NOT in your public Music folder. Uninstalling the app or wiping the phone deletes private recordings; tapping <strong>Share</strong> exports a separate copy to the target app.</li></ul>"],["4. Note Tags & Tag Filtering","Assign or create custom <code>#tags</code> using the <strong>#</strong> button and filter across titles & notes via the top Funnel menu (single or multi-tag OR filter). Deleted tags stay removed permanently."],["5. Global Search","Search simultaneously across all titles and note contents (excluding Trash) and jump straight to the matching note."],["6. Android Home Screen Widget","Add the Voice Note widget to your Home Screen to launch Voice Dictation in one tap. If App Lock is enabled, Android authentication is required before dictation opens."],["7. Professional PDF Project Report","Generate shareable A4 PDF project reports per title with notes, tags, timestamps, audio/attachment summaries, and images."],["8. Device & Google Drive Backup","<ul><li><strong>Quick Text Backup (.json):</strong> Lightweight JSON export for notes and titles only (no audio, photos, or videos).</li><li><strong>Full Backup (.zip):</strong> Saves notes together with photos, videos, audio recordings, and file attachments in an unencrypted <code>.zip</code> archive under <em>Back Up to Device</em> (<em>Include media files</em> starts checked; unchecking archives text and note structure only).</li><li><strong>Google Drive Backup (Optional / Unencrypted ZIP):</strong> Connect your own Google account via <code>drive.file</code> scope to manually back up and restore <strong>unencrypted ZIP</strong> archives (text-only or with media; media defaults to OFF) in visible <strong>My Drive › İcat Defteri › Yedekler</strong>.</li><li><strong>No Extra Password Encryption:</strong> Local (.json / .zip) and Google Drive (.zip) backups are not additionally encrypted with a password by İcat Defteri.</li><li><strong>Restore Modes:</strong> Restore local backups via <em>Menu › Back Up to Device › Restore / Import Backup</em> or from Google Drive using <em>Merge (Safe)</em> or confirmed <em>Overwrite</em>.</li></ul>"],["9. Five Themes","Choose between Dark Neon, Light, Pure AMOLED, Midnight, and Graphite from the sidebar theme selector."],["10. Manual Drag-and-Drop Sorting","Select <strong>Manual Sort</strong> from the sort menu to reorder titles and notes via drag handles; order persists automatically."],["11. Images, Videos, Files & Drawings","Attach gallery files, videos, documents (up to <strong>200 MB</strong> per file), camera photos, or sketches. Attached files are copied into independent app-private storage (<code>files/attachments/</code>), so deleting the original source file later in Gallery/Downloads will NOT break your note attachment."],["12. Sketchpad & Fullscreen Mode","Tap the top-right expand button in the sketchpad to draw fullscreen. Strokes are stored as resolution-independent vectors so expanding, shrinking, or pressing Hardware Back once preserves your entire drawing."],["13. Reminders, Calendar & Text-to-Speech (TTS)","Set one-time or recurring reminders and review them in the Calendar view. Exempt the app from strict battery optimization if your device delays alarms. Use the speaker icon inside note details for offline/local TTS playback."],["14. Biometric / Device App Lock","Enable App Lock in the sidebar to guard access with your Android fingerprint, face unlock, PIN, or pattern. İcat Defteri stores no biometric data."],["15. Trash Bin & Permanent Deletion","Deleted items remain in Trash for <strong>30 days</strong> with their audio/attachment files intact. Permanent deletion (or 30-day expiry) deletes the app-private copies under <code>files/recordings/</code> and <code>files/attachments/</code> without touching original external files."],["16. Changing Phones & Migration","Use <code>.json</code> or no-media ZIP backups for text-only migration (missing media notes remain readable and mark files as missing), or keep <strong>Include media files</strong> enabled for full <code>.zip</code> device or Google Drive migration."],["17. Data Loss Prevention","Backups stored only on the same phone are lost if the phone is lost or reset. Always keep a verified off-device <code>.json</code> or <code>.zip</code> copy (your Google Drive account, email, or computer)."],["18. FAQ & Support","Disconnecting Google Drive removes the local session token without deleting existing files already stored in your Drive folder. Contact: Ramazan Kocatürk — <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a>"]]},"de":{"badge":"Offizielles Handbuch","title":"İcat Defteri — Benutzerhandbuch","meta":"Stand: 21. November 2026 • 18 Abschnitte • 7 Sprachen","sections":[["1. Ersteinrichtung, Sprache & Berechtigungen","İcat Defteri unterstützt <strong>7 Sprachen</strong> (TR, EN, DE, FR, ES, IT, PT). Berechtigungen: <strong>Mikrofon</strong> (nur beim Diktieren oder .m4a-Aufnehmen), <strong>Benachrichtigungen</strong> (Erinnerungen) und optional <strong>Kamera</strong>."],["2. Titel, Neon-Akzente & Notizen","Erstellen Sie Titel mit Neon-Seitenstreifen und nutzen Sie im <strong>+</strong>-Menü Textnotiz, Spracheingabe (Diktat) oder echte M4A-Audioaufnahme."],["3. Spracheingabe vs. echte M4A-Aufnahme","Diktate transkribieren live über Android/Google Speech Services ohne Rohaudio zu speichern. Echte <code>.m4a</code>-Aufnahmen liegen privat unter <code>files/recordings/</code> (nicht im öffentlichen Musikordner); Deinstallation löscht sie, <strong>Teilen</strong> sendet eine separate Kopie."],["4. Tags & Tag-Filter","Fügen Sie <code>#Tags</code> hinzu und filtern Sie im Trichter-Menü (einzeln oder mehrfach mit ODER-Logik). Gelöschte Tags bleiben entfernt."],["5. Globale Suche","Durchsuchen Sie alle Titel und Notizen außerhalb des Papierkorbs sofort nach Stichwörtern."],["6. Startbildschirm-Widget","Starten Sie das Sprachdiktat mit einem Tippen vom Android-Startbildschirm; bei aktivierter App-Sperre ist vorher eine Entsperrung nötig."],["7. PDF-Projektbericht","Exportieren Sie A4-PDF-Berichte je Titel inklusive Notizen, Tags, Medienübersicht und Bildern."],["8. Geräte- & Google-Drive-Backup","<strong>Auf Gerät sichern:</strong> Schnelles Text-Backup als leichtgewichtiges <code>.json</code> (nur Text/Titel) oder vollständiges unverschlüsseltes <code>.zip</code>-Archiv (inkl. Medien standardmäßig aktiv; ohne Medien nur Textstruktur). <strong>Google Drive:</strong> Manuelle <strong>unverschlüsselte ZIP-Backups</strong> (mit oder ohne Medien, standardmäßig ohne Medien) im Ordner <em>İcat Defteri / Yedekler</em> (Scope <code>drive.file</code>). Weder lokale (.json / .zip) noch Google Drive-Backups (.zip) werden von İcat Defteri zusätzlich mit einem Passwort verschlüsselt."],["9. Fünf Designs","Wählen Sie zwischen Dark Neon, Light, Pure AMOLED, Midnight und Graphite."],["10. Manuelle Sortierung per Drag & Drop","Aktivieren Sie im Sortiermenü <strong>Manuelle Sortierung</strong>, um Titel und Notizen per Ziehen frei anzuordnen."],["11. Anhänge & Unabhängige Kopien","Bilder, Videos, PDFs/Dokumente (bis <strong>200 MB</strong>) und Skizzen werden als <strong>unabhängige Kopie</strong> nach <code>files/attachments/</code> kopiert; Löschen der Ursprungsdatei in der Galerie beeinträchtigt den Anhang nicht."],["12. Zeichenbrett & Vollbildmodus","Erweitern Sie die Zeichenfläche über das Symbol oben rechts. Vektor-Speicherung schützt Linien bei Größe/Zurück-Taste."],["13. Erinnerungen, Kalender & TTS","Einmalige oder wiederkehrende Alarme, Kalenderansicht und lokale Sprachausgabe (TTS)."],["14. Biometrische App-Sperre","Nutzen Sie Fingerabdruck, Gesichtserkennung, PIN oder Muster Ihres Android-Geräts."],["15. Papierkorb (30 Tage) & Endgültiges Löschen","Gelöschte Einträge bleiben 30 Tage wiederherstellbar; endgültiges Löschen entfernt nur die App-internen Dateien."],["16. Gerätewechsel","Für vollständigen Umzug inkl. Audio & Dateien aktivieren Sie <em>Medien einschließen</em> vor dem Export/Upload."],["17. Datenschutz- & Backuptipps","Bewahren Sie geprüfte Backups außerhalb des Smartphones auf (z. B. Google Drive oder PC)."],["18. FAQ & Kontakt","Trennen des Drive-Kontos löscht keine Dateien in Drive. Support: <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a>"]]},"fr":{"badge":"Guide Officiel","title":"İcat Defteri — Guide d’Utilisation","meta":"Mise à jour : 21 novembre 2026 • 18 sections • 7 langues","sections":[["1. Configuration, Langues & Autorisations","İcat Defteri prend en charge <strong>7 langues</strong>. Autorisations : <strong>Microphone</strong> (dictée ou audio .m4a uniquement), <strong>Notifications</strong> (rappels) et <strong>Appareil photo</strong> sur action explicite."],["2. Titres, Bordures Néon & Notes","Créez des titres avec bordure néon et choisissez entre Note texte, Dictée vocale ou Enregistrement audio .m4a."],["3. Dictée vs Enregistrement M4A réel","La dictée transcrit en direct sans garder l'audio brut. Les fichiers <code>.m4a</code> sont stockés en privé dans <code>files/recordings/</code> (hors dossier Musique public). Partager envoie une copie distincte ; désinstaller l'app supprime ce stockage privé."],["4. Étiquettes & Filtrage","Ajoutez des <code>#tags</code> et filtrez via l'icône entonnoir (sélection simple ou multiple OU)."],["5. Recherche Globale","Recherchez instantanément dans tous les titres et notes actifs (corbeille exclue)."],["6. Widget Android","Lancez la dictée depuis l'écran d'accueil ; protégé par le verrouillage de l'application s'il est activé."],["7. Rapport PDF Professionnel","Générez des rapports PDF A4 complets par titre et partagez-les."],["8. Sauvegarde Appareil & Google Drive","<strong>Sur l'appareil :</strong> sauvegarde texte rapide en <code>.json</code> (notes/titres uniquement) ou sauvegarde complète en <strong>ZIP non chiffré</strong> (médias cochés par défaut ; sans médias, seul le texte est archivé). <strong>Google Drive :</strong> sauvegarde et restauration manuelles au format <strong>ZIP non chiffré</strong> uniquement (médias désactivés par défaut) dans <em>İcat Defteri / Yedekler</em> (<code>drive.file</code>). Ni les sauvegardes locales (.json / .zip) ni celles sur Google Drive (.zip) ne sont chiffrées en plus par mot de passe par İcat Defteri."],["9. Cinq Thèmes","Sombre Néon, Clair, AMOLED Pur, Minuit et Graphite."],["10. Tri Manuel Glisser-Déposer","Réorganisez librement titres et notes en activant le tri manuel."],["11. Pièces Jointes & Copies Indépendantes","Images, vidéos, PDF/documents (max. <strong>200 Mo</strong>) et dessins sont copiés de manière indépendante dans <code>files/attachments/</code>. Supprimer le fichier source dans la Galerie n'affecte pas la note."],["12. Tableau de Dessin Plein Écran","Agrandissez le canevas sans perte vectorielle ; le bouton Retour réduit d'abord le plein écran."],["13. Rappels, Calendrier & Lecture (TTS)","Rappels uniques ou récurrents avec vue Calendrier et synthèse vocale locale."],["14. Verrouillage Biométrique / PIN","Sécurité matérielle Android (empreinte, visage, PIN ou schéma) sans stockage côté développeur."],["15. Corbeille (30 Jours) & Suppression Définitive","Rétention de 30 jours avant suppression permanente des copies privées <code>recordings</code> et <code>attachments</code>."],["16. Changement de Téléphone","Activez <em>Inclure les médias</em> lors de la sauvegarde pour transférer aussi vos audios et fichiers."],["17. Prévention des Pertes de Données","Conservez toujours une copie vérifiée hors de votre téléphone."],["18. FAQ & Support","Déconnecter Google Drive ne supprime pas les fichiers déjà enregistrés sur Drive. Contact : <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a>"]]},"es":{"badge":"Guía Oficial","title":"İcat Defteri — Guía de Uso","meta":"Actualización: 21 de noviembre de 2026 • 18 secciones • 7 idiomas","sections":[["1. Configuración, Idioma y Permisos","Compatible con <strong>7 idiomas</strong>. Permisos: <strong>Micrófono</strong> (solo al dictar o grabar .m4a), <strong>Notificaciones</strong> (recordatorios) y <strong>Cámara</strong> bajo acción del usuario."],["2. Títulos, Bordes Neón y Notas","Crea títulos con acentos neón y elige entre Nota de texto, Dictado por voz o Grabación de audio .m4a."],["3. Dictado vs Grabación M4A Real","El dictado convierte voz a texto sin guardar audio sin procesar. Los archivos <code>.m4a</code> se guardan en almacenamiento privado (<code>files/recordings/</code>), NO en Música pública. Compartir crea una copia aparte; desinstalar borra este almacenamiento privado."],["4. Etiquetas y Filtrado","Asigna <code>#etiquetas</code> y filtra por una o varias etiquetas desde el menú de filtro."],["5. Búsqueda Global","Busca en todos los títulos y notas activos excluyendo la Papelera."],["6. Widget de Pantalla de Inicio","Inicia el dictado rápido desde Android; protegido por bloqueo biométrico si está activo."],["7. Informe PDF Profesional","Exporta informes PDF A4 con notas, etiquetas, resumen multimedia e imágenes."],["8. Copia en Dispositivo y Google Drive","<strong>En dispositivo:</strong> copia rápida de texto en <code>.json</code> (solo notas y títulos) o copia completa en <strong>ZIP sin cifrar</strong> (medios activados por defecto; si se desactivan, solo se archiva texto). <strong>Google Drive:</strong> copias y restauraciones manuales en formato <strong>ZIP sin cifrar</strong> (medios desactivados por defecto) en <em>İcat Defteri / Yedekler</em> (<code>drive.file</code>). İcat Defteri no cifra adicionalmente con contraseña ni las copias locales (.json / .zip) ni las de Google Drive (.zip)."],["9. Cinco Temas","Oscuro Neón, Claro, AMOLED Puro, Medianoche y Grafito."],["10. Orden Manual Arrastrar y Soltar","Activa el orden manual para reordenar títulos y notas arrastrando."],["11. Adjuntos y Copias Independientes","Fotos, vídeos, PDF/documentos (máx. <strong>200 MB</strong>) y dibujos se copian de forma independiente en <code>files/attachments/</code>; borrar el original de la Galería no borra el adjunto en la app."],["12. Pizarra de Dibujo a Pantalla Completa","Amplía el lienzo conservando los trazos vectoriales; el botón Atrás sale primero de pantalla completa."],["13. Recordatorios, Calendario y TTS","Alarmas puntuales o periódicas, vista Calendario y lectura en voz alta local."],["14. Bloqueo Biométrico / PIN","Usa huella, rostro, PIN o patrón de Android sin guardar claves en servidores."],["15. Papelera (30 Días) y Borrado Permanente","Retención de 30 días; el borrado definitivo elimina las copias privadas internas sin tocar tus originales externos."],["16. Cambio de Teléfono","Activa <em>Incluir medios</em> para migrar grabaciones .m4a y adjuntos a un nuevo móvil."],["17. Consejos contra Pérdida de Datos","Guarda una copia verificada fuera del teléfono (Google Drive o PC)."],["18. Preguntas Frecuentes y Soporte","Desconectar Google Drive no elimina copias ya subidas. Contacto: <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a>"]]},"it":{"badge":"Guida Ufficiale","title":"İcat Defteri — Guida Utente","meta":"Aggiornamento: 21 novembre 2026 • 18 sezioni • 7 lingue","sections":[["1. Configurazione, Lingua e Permessi","Supporta <strong>7 lingue</strong>. Permessi: <strong>Microfono</strong> (solo durante dettatura o registrazione .m4a), <strong>Notifiche</strong> (promemoria) e <strong>Fotocamera</strong> su azione esplicita."],["2. Titoli, Bordi Neon e Note","Crea titoli con bordi neon e scegli tra Nota di testo, Dettatura vocale o Registrazione audio .m4a."],["3. Dettatura vs Registrazione M4A Reale","La dettatura trascrive senza salvare audio grezzo. I file <code>.m4a</code> risiedono in spazio privato dell'app (<code>files/recordings/</code>), non nella cartella Musica pubblica; la disinstallazione elimina tali file e Condividi crea una copia separata."],["4. Tag e Filtro per Tag","Gestisci i <code>#tag</code> e filtra note e titoli tramite il menu filtro (OR su più tag)."],["5. Ricerca Globale","Cerca istantaneamente tra tutti i titoli e le note attive (cestino escluso)."],["6. Widget Schermata Home","Avvia rapidamente la dettatura vocale dalla Home Android, rispettando il blocco app se attivo."],["7. Report PDF Professionale","Esporta report A4 in PDF per ogni titolo con note, tag e riepilogo allegati."],["8. Backup Dispositivo e Google Drive","<strong>Su dispositivo:</strong> backup rapido di testo in <code>.json</code> (solo note e titoli) oppure backup completo in <strong>ZIP non crittografato</strong> (media inclusi di default; disattivandoli si archivia solo il testo). <strong>Google Drive:</strong> backup e ripristini manuali in formato <strong>ZIP non crittografato</strong> (media disattivati di default) in <em>İcat Defteri / Yedekler</em> (<code>drive.file</code>). Né i backup locali (.json / .zip) né quelli su Google Drive (.zip) vengono ulteriormente crittografati con password da İcat Defteri."],["9. Cinque Temi","Scuro Neon, Chiaro, AMOLED Puro, Mezzanotte e Grafite."],["10. Ordinamento Manuale Drag & Drop","Attiva l'ordinamento manuale per spostare liberamente titoli e note."],["11. Allegati e Copie Indipendenti","Immagini, video, PDF/documenti (fino a <strong>200 MB</strong>) e disegni vengono copiati in modo indipendente in <code>files/attachments/</code>; eliminare l'originale dalla Galleria non rimuove l'allegato."],["12. Lavagna Disegno a Schermo Intero","Espandi l'area di disegno mantenendo i tratti vettoriali intatti."],["13. Promemoria, Calendario e TTS","Allarmi singoli o ricorrenti, vista Calendario e sintesi vocale locale."],["14. Blocco Biometrico / Dispositivo","Proteggi le note con impronta, volto, PIN o sequenza Android."],["15. Cestino (30 Giorni) e Cancellazione Definitiva","I dati eliminati restano nel cestino per 30 giorni; l'eliminazione definitiva cancella le copie interne all'app."],["16. Cambio Dispositivo","Attiva <em>Includi media</em> per trasferire anche registrazioni .m4a e allegati."],["17. Prevenzione Perdita Dati","Conserva sempre una copia di backup verificata fuori dallo smartphone."],["18. FAQ e Supporto","Scollegare Drive non elimina i file già caricati su Drive. Contatto: <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a>"]]},"pt":{"badge":"Guia Oficial","title":"İcat Defteri — Guia de Uso","meta":"Atualização: 21 de novembro de 2026 • 18 seções • 7 idiomas","sections":[["1. Configuração, Idioma e Permissões","Suporta <strong>7 idiomas</strong>. Permissões: <strong>Microfone</strong> (apenas ao ditar ou gravar .m4a), <strong>Notificações</strong> (lembretes) e <strong>Câmera</strong> sob ação do usuário."],["2. Títulos, Bordas Neon e Notas","Crie títulos com bordas neon e escolha entre Nota de texto, Ditado por voz ou Gravação de áudio .m4a."],["3. Ditado vs Gravação M4A Real","O ditado transcreve ao vivo sem salvar áudio bruto. Gravações <code>.m4a</code> ficam em área privada (<code>files/recordings/</code>), não na pasta Música pública. Compartilhar gera cópia separada; desinstalar apaga esse armazenamento privado."],["4. Tags e Filtro por Tags","Adicione <code>#tags</code> personalizadas e filtre notas pelo menu de funil."],["5. Busca Global","Pesquise instantaneamente em títulos e textos ativos (excluindo a Lixeira)."],["6. Widget na Tela Inicial","Inicie o ditado de voz direto da tela inicial Android, respeitando o bloqueio do app."],["7. Relatório PDF Profissional","Exporte relatórios A4 em PDF por título com notas, tags e resumo de mídia."],["8. Backup no Dispositivo e Google Drive","<strong>No dispositivo:</strong> backup rápido de texto em <code>.json</code> (apenas notas e títulos) ou backup completo em <strong>ZIP sem criptografia</strong> (mídia marcada por padrão; ao desmarcar, apenas texto é arquivado). <strong>Google Drive:</strong> backups e restaurações manuais em formato <strong>ZIP sem criptografia</strong> (mídia desativada por padrão) em <em>İcat Defteri / Yedekler</em> (<code>drive.file</code>). Nem os backups locais (.json / .zip) nem os do Google Drive (.zip) são criptografados adicionalmente com senha pelo İcat Defteri."],["9. Cinco Temas","Escuro Neon, Claro, AMOLED Puro, Meia-Noite e Grafite."],["10. Ordenação Manual Arrastar e Soltar","Ative a ordem manual para reordenar títulos e notas como preferir."],["11. Anexos e Cópias Independentes","Fotos, vídeos, PDFs/documentos (até <strong>200 MB</strong>) e desenhos são copiados de forma independente em <code>files/attachments/</code>; apagar o original da Galeria não afeta o anexo na nota."],["12. Quadro de Desenho em Tela Cheia","Expanda a tela de desenho preservando traços vetoriais em qualquer rotação."],["13. Lembretes, Calendário e TTS","Alarmes únicos ou recorrentes, visão de Calendário e leitura em voz alta local."],["14. Bloqueio Biométrico / PIN","Use digital, reconhecimento facial, PIN ou padrão do Android."],["15. Lixeira (30 Dias) e Exclusão Permanente","Itens apagados permanecem 30 dias antes da remoção definitiva das cópias privadas internas."],["16. Troca de Celular","Marque <em>Incluir mídia</em> ao gerar backup completo para migrar áudios .m4a e anexos."],["17. Prevenção de Perda de Dados","Mantenha sempre uma cópia verificada fora do telefone (Drive ou PC)."],["18. Perguntas Frequentes e Suporte","Desconectar o Google Drive não apaga arquivos já enviados ao Drive. Contato: <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a>"]]}};
  var LEGAL = {"tr":{"privacy":{"badge":"Şeffaflık & Veri Güvenliği Bilgilendirmesi","title":"İcat Defteri – Gizlilik Politikası ve KVKK Aydınlatma Özeti","meta":"Son Güncelleme: 21 Kasım 2026 • Kullanılabilir özellikler yüklü uygulama sürümüne göre değişebilir","highlight":"🛡️ <strong>Temel İlke:</strong> Geliştirici kullanıcıların notlarını, ses kayıtlarını veya dosya eklerini kendi sunucularında toplamaz ve barındırmaz. Uygulamada otomatik bulut eşitlemesi ve Android AutoBackup (<code>allowBackup=false</code>) yoktur; veriler Kullanıcı'nın kendi başlattığı Paylaş, PDF/Yedek Dışa Aktar, canlı Google Ses Hizmetleri diktesi veya isteğe bağlı Google Drive (<code>drive.file</code>) işlemleri dışında cihazdan çıkarılmaz.","sections":[["1. Veri Sorumlusu ve Kapsam","<p>6698 sayılı Kişisel Verilerin Korunması Kanunu (\"KVKK\") uyarınca veri sorumlusu Uygulama geliştiricisi <strong>Ramazan Kocatürk</strong>'tür (<code>ramazankocaturk@gmail.com</code>). Bu metin İcat Defteri uygulamasındaki yerel not/dikte, M4A ses kaydı, bağımsız dosya ekleri ve desteklenen uygulama sürümlerinde kullanıcı tarafından isteğe bağlı olarak etkinleştirilen Google Drive yedekleme davranışını açıklar. Kullanılabilir özellikler, yüklü uygulama sürümüne göre değişebilir.</p>"],["2. Sesle Yazma (Dikte) ve M4A Ses Kaydı","<ul><li><strong>Sesle Yaz (Dikte):</strong> Konuşmanın metne dönüştürülmesi Android/Google Ses Hizmetleri üzerinden sağlanır; cihaz ayarlarına göre ses verisi tanıma amacıyla Google tarafından çevrimiçi işlenebilir. Diktede ham ses kaydı tutulmaz.</li><li><strong>Gerçek M4A Ses Kaydı:</strong> Oluşturulan <code>.m4a</code> dosyaları yalnızca cihazdaki uygulamaya özel <code>files/recordings/</code> dizininde saklanır (ortak Müzik klasörüne yazılmaz). Geliştirici bu kayıtlara erişemez; paylaşım yapıldığında alıcı uygulamaya ayrı kopya gider.</li></ul>"],["3. Cihazda Yerel Saklanan Veriler ve Bağımsız Ek Kopyaları","<p>Başlıklar, notlar, etiketler, hatırlatıcılar, çöp kutusu öğeleri (30 gün), tema/dil/sıralama tercihleri, uygulama kilidi tercihi (<code>BiometricPrompt</code>; biyometrik şablonlar asla alınmaz), ses kayıtları (<code>files/recordings/</code>) ve ek kopyaları (<code>files/attachments/</code>, max 200 MB) yalnızca cihazda saklanır. Drive bağlıyken seçilen hesap e-postası ve klasör kimlikleri cihazdaki <code>SharedPreferences</code> alanında tutulur ve bağlantı kesilince temizlenir.</p>"],["4. Kullanılan İzinler ve Amaçları","<ul><li><strong>Mikrofon (RECORD_AUDIO):</strong> Yalnızca Kullanıcı dokunduğunda dikte veya M4A kayıt için kullanılır; arka planda dinleme yapılmaz.</li><li><strong>Bildirim / Tam Alarm (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED):</strong> Kurulan hatırlatıcıları zamanında göstermek ve cihaz açılışında yenilemek için kullanılır.</li><li><strong>Kamera & Dosya Seçici (SAF):</strong> Yalnızca Kullanıcı fotoğraf çekmek veya dosya/yedek seçmek istediğinde sistem penceresini açar.</li><li><strong>Ağ Erişimi (INTERNET / ACCESS_NETWORK_STATE):</strong> Yalnızca çevrimiçi ses tanıma ve Kullanıcının kendi başlattığı Google Drive (<code>drive.file</code>) işlemleri için kullanılır.</li></ul>"],["5. İsteğe Bağlı Google Drive Yedekleme ve Veri Güvenliği","<ul><li>Kullanıcı dilerse kendi Google hesabını seçerek <strong>yalnızca</strong> uygulamanın oluşturduğu dosyaları kapsayan <code>https://www.googleapis.com/auth/drive.file</code> yetkisiyle, kendi başlattığı işlemler sonucunda <em>Drive'ım › İcat Defteri › Yedekler</em> klasörüne <strong>ZIP</strong> formatında yedek aktarabilir.</li><li>Yedekler Geliştirici hesabına değil Kullanıcının kendi Google Drive alanına gider; Google'ın gizlilik koşulları (<code>policies.google.com/privacy</code>) uygulanır.</li><li><strong>Medya ve Şifreleme Bilgisi:</strong> Google Drive yedeklemesinde medya seçeneği varsayılan kapalıdır. Hem yerel yedekler (<code>.json</code> / <code>.zip</code>) hem de Google Drive yedekleri (<code>.zip</code>) şifresiz olarak kaydedilir ve İcat Defteri tarafından ayrıca parola ile şifrelenmez; şifresiz yedek dosyaları kişisel not ve medya içerebilir.</li><li><strong>Bağlantıyı Kesme:</strong> Hesap bağlantısını kesmek cihazdaki oturumu/tokenı temizler; Drive'daki mevcut yedekleri otomatik silmez.</li></ul>"],["6. Analitik, Reklam ve Paylaşım","<p>Uygulamada AdMob veya reklam SDK'sı, Firebase Analytics / Crashlytics izleme aracı veya geliştiriciye ait merkezi kullanıcı sunucusu yoktur. <em>Paylaş</em> ve <em>PDF Paylaş</em> işlemleri yalnızca Kullanıcının seçtiği uygulamaya ayrı kopya aktarır; PDF belgeleri hassas not ve ek özetleri içerebilir.</p>"],["7. Saklama, İmha, Yurt Dışı Değerlendirme ve KVKK Madde 11 Hakları","<p>Silinen öğeler 30 gün yerel çöp kutusunda bekletilir; kalıcı silmede (<code>permDelete</code> / <code>cleanupTrash</code> / yetim dosya temizliği) başka kaydın kullanmadığı özel kopyalar silinir. Uygulama kaldırıldığında <code>allowBackup=false</code> nedeniyle cihaz içi özel veriler silinir, ancak önceden dışa aktarılan veya Drive'a yüklenen dosyalar kendi konumlarında kalır. Geliştirici sunucularına aktarım olmamakla birlikte, kullanıcının başlattığı çevrimiçi dikte, Paylaş ve Google Drive (Google LLC) işlemlerindeki yurt dışı aktarım boyutu KVKK Madde 9 kapsamında yayın öncesi değerlendirme konusudur. KVKK m.10/11 kapsamındaki bilgi, düzeltme, silme ve itiraz başvurularınız için: <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Geliştirici: Ramazan Kocatürk","title":"İcat Defteri – Kullanıcı Sözleşmesi","meta":"Son Güncelleme: 21 Kasım 2026 • Kullanılabilir özellikler yüklü uygulama sürümüne göre değişebilir","highlight":"","sections":[["1. Taraflar, Kapsam ve Sürüm Ayrımı","<p>İşbu Kullanıcı Sözleşmesi (\"Sözleşme\"), İcat Defteri mobil uygulamasını (\"Uygulama\") kullanan gerçek kişi (\"Kullanıcı\") ile geliştirici <strong>Ramazan Kocatürk</strong> (\"Geliştirici\") arasında akdedilmiştir. V1 yayınındaki yerel özelliklerin yanında V2.0 ile eklenen M4A ses kaydı, ek dosyalar, çizim, PDF rapor ve isteğe bağlı Google Drive yedekleme özellikleri ilgili sürüm aktif edildiğinde bu şartlara tabidir.</p>"],["2. Yerel Öncelikli Mimari ve Opsiyonel Google Drive","<p>İcat Defteri yerel öncelikli (local-first) çalışır:</p><ul><li>Notlar, başlıklar, etiketler, hatırlatıcılar, M4A ses kayıtları (<code>files/recordings/</code>) ve dosya ekleri (<code>files/attachments/</code>) yalnızca Kullanıcı cihazında tutulur.</li><li>Geliştiricinin kendi barındırdığı bulut veritabanı veya arka planda otomatik bulut senkronizasyon sunucusu <strong>yoktur</strong>.</li><li>Google Drive yedeklemesi (<code>drive.file</code>) tamamen isteğe bağlıdır; yalnızca Kullanıcı hesap bağlayıp yedekleme başlattığında Kullanıcı'nın kendi Google Drive alanındaki <em>İcat Defteri / Yedekler</em> klasörüne yükleme yapılır. Google Drive yedekleme özelliği, desteklenen uygulama sürümlerinde kullanıcı tarafından isteğe bağlı olarak etkinleştirilir; kullanılabilir özellikler yüklü uygulama sürümüne göre değişebilir.</li></ul>"],["3. Veri Kaybı Riski, Yedek Biçimleri ve Kullanıcı Sorumluluğu","<div class=\"warning-box\"><strong>ÖNEMLİ UYARI:</strong> Uygulamada Android otomatik bulut yedeklemesi kapalıdır (<code>allowBackup=false</code>). Telefonun kaybolması, çalınması, bozulması, sıfırlanması veya İcat Defteri'nin kaldırılması hâlinde cihazdaki tüm yerel veriler kalıcı olarak silinebilir. Yalnızca telefon hafızasında tutulan yedek de cihaz kaybıyla birlikte erişilemez olur; doğrulanmış bir yedeği cihaz dışında saklamak Kullanıcı'nın sorumluluğundadır.</div><ul><li><strong>Yerel Yedekleme (Cihaza Yedekle — .json / .zip):</strong> <em>Hızlı Metin Yedeği (.json)</em> yalnızca metin/not yapısını yedekler; M4A ses, fotoğraf, video ve ekleri <strong>içermez</strong>. <em>Tam Yedek (.zip)</em> medya seçeneği açıkken desteklenen ses ve ekleri, kapalıyken yalnızca metin ve not yapısını <strong>şifresiz ZIP</strong> olarak paketler. Yerel yedekler İcat Defteri tarafından ayrıca parola ile şifrelenmez.</li><li><strong>Google Drive Yedekleme (Şifresiz ZIP):</strong> Kullanıcı kendi Google hesabına medyalı veya medyasız olarak yalnızca <strong>şifresiz ZIP</strong> formatında manuel yedek aktarabilir (depolama alanı, Drive kotası ve internet bağlantısı gerekir). Google Drive yedekleri İcat Defteri tarafından ayrıca parola ile şifrelenmez.</li><li><strong>Geri Yükleme:</strong> <em>Birleştir</em> mevcut verilere yeni öğeleri ekler; <em>Üzerine Yaz</em> onay sonrası yerel kayıtları seçilen yedekle değiştirir (öncesinde güncel yedek alınması önerilir).</li></ul>"],["4. Ses İşleme, Dosya Ekleri ve Çöp Kutusu","<ul><li>Canlı sesle yazma (dikte), Android/Google Ses Hizmetleri altyapısını kullanır ve ham ses kaydetmez.</li><li><em>Ses Kaydet (.m4a)</em> özelliği sesi cihazın halka açık Müzik klasörüne değil uygulamaya özel <code>files/recordings/</code> alanına kaydeder. Kayıt eksikse not korunur ancak dosya eksik uyarısı gösterilir.</li><li>Fotoğraf, video, belge (200 MB sınırı) ve çizimler <code>files/attachments/</code> içine bağımsız kopya olarak alınır; kaynak dosyanın galeriden silinmesi bu kopyayı silmez, uygulamadaki kalıcı silme işlemi de telefonunuzdaki orijinal galeri dosyasına dokunmaz. Paylaşma/PDF dışa aktarımı ayrı kopya üretir.</li></ul>"],["5. Sorumluluğun Sınırlandırılması","<p>Sorumluluğun sınırlandırılması yalnızca yürürlükteki hukukun izin verdiği ölçüde geçerlidir; tüketicinin vazgeçilemeyen yasal haklarını ortadan kaldırmak üzere yorumlanamaz. Cihaz arızası, sıfırlama, silme, yedek almama veya pil optimizasyonu kaynaklı alarm gecikmeleri Geliştirici kontrolü dışındadır. Uygulama \"olduğu gibi\" sunulur; Google Drive ve konuşma servisleri üçüncü taraf sağlayıcı koşullarına tabidir. Google hesabı bağlantısını kesmek Drive'daki mevcut yedekleri silmez.</p>"],["6. Fikri Mülkiyet, Gizlilik ve İletişim","<p>Uygulama kodları, arayüz ve marka hakları Ramazan Kocatürk'e; Kullanıcı'nın oluşturduğu tüm fikir, ses, görsel ve not içerikleri tamamen Kullanıcı'ya aittir. Sözleşme onayı tek başına tüm isteğe bağlı izinler için sınırsız rıza sayılmaz; kişisel veri detayları Gizlilik Politikası ve KVKK Aydınlatma Metni'ndedir.<br><strong>E-posta:</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}},"en":{"privacy":{"badge":"Transparency & Data Security Notice","title":"İcat Defteri – Privacy Policy & KVKK Transparency Notice","meta":"Last Updated: November 21, 2026 • Available features may vary by installed app version","highlight":"🛡️ <strong>Core Principle:</strong> The Developer does not collect or host user notes, voice recordings, or attachments on developer servers. Automatic cloud sync and Android AutoBackup (<code>allowBackup=false</code>) are disabled; data leaves the device only upon User-initiated Share, PDF/Backup export, live Google Speech dictation, or optional personal Google Drive (<code>drive.file</code>) backup.","sections":[["1. Data Controller & Scope","<p>The data controller under applicable privacy law and Turkish Personal Data Protection Law No. 6698 (\"KVKK\") is developer <strong>Ramazan Kocatürk</strong> (<code>ramazankocaturk@gmail.com</code>). This policy covers local notes/dictation, M4A audio recording, independent file attachments, and optional Google Drive backup enabled voluntarily by the user in supported app versions. Available features may vary depending on the installed app version.</p>"],["2. Voice Dictation vs. M4A Audio Recording","<ul><li><strong>Voice Dictation:</strong> Speech-to-text conversion uses Android/Google Speech Services; depending on device settings, speech may be processed online by Google for recognition. İcat Defteri retains text only and saves no raw dictation audio.</li><li><strong>Real M4A Recording:</strong> Created <code>.m4a</code> files are written strictly to app-private internal storage (<code>files/recordings/</code>), never to shared Music folders. The Developer cannot access them; tapping Share sends a separate copy to the chosen app.</li></ul>"],["3. Locally Stored Data & Independent Copies","<p>Titles, notes, tags, reminders, Trash items (30 days), theme/language/sort settings, App Lock preference (<code>BiometricPrompt</code>; biometric templates are never accessed or stored), M4A recordings (<code>files/recordings/</code>), and copied attachments (<code>files/attachments/</code>, max 200 MB/file) stay local. While Google Drive is connected, chosen account email and folder IDs are cached in device <code>SharedPreferences</code> and cleared upon disconnect.</p>"],["4. Permissions & Purposes","<ul><li><strong>Microphone (RECORD_AUDIO):</strong> Used solely when the User taps dictation or M4A recording; never listens in the background.</li><li><strong>Notifications & Exact Alarms (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED):</strong> Delivers scheduled note reminders on time and reschedules them after reboot.</li><li><strong>Camera & System File Picker (SAF):</strong> Opens the camera or Android file picker only upon explicit User action.</li><li><strong>Network Access (INTERNET / ACCESS_NETWORK_STATE):</strong> Used only for online speech recognition and User-initiated Google Drive (<code>drive.file</code>) transfers.</li></ul>"],["5. Optional Google Drive Backup & Security","<ul><li>Users may voluntarily link their own Google account under the minimal <code>https://www.googleapis.com/auth/drive.file</code> scope (restricted strictly to files created by this app) to transfer backups in <strong>ZIP</strong> format to <em>My Drive › İcat Defteri › Yedekler</em> upon User-initiated action.</li><li>Backups go to the User's own Drive account—not any Developer account—under Google's privacy terms (<code>policies.google.com/privacy</code>).</li><li><strong>Media & Encryption Notice:</strong> Media inclusion defaults to OFF on Google Drive. Both local device backups (<code>.json</code> / <code>.zip</code>) and Google Drive backups (<code>.zip</code>) are saved without additional password encryption by İcat Defteri; unencrypted backup files may contain personal notes and included media.</li><li><strong>Disconnecting:</strong> Disconnecting clears local OAuth session state/token without automatically deleting backups already stored in your Drive.</li></ul>"],["6. Analytics, Advertising & Sharing","<p>İcat Defteri contains no AdMob/ad SDKs, no Firebase Analytics/Crashlytics tracking, and no developer user accounts. <em>Share</em> and <em>Share PDF</em> transfer a separate User-triggered copy to your chosen target app; exported PDFs may contain sensitive notes or attachment summaries.</p>"],["7. Retention, Deletion, Cross-Border Note & Statutory Rights (KVKK Art. 10/11)","<p>Deleted items stay in local Trash for 30 days; permanent deletion (<code>permDelete</code> / <code>cleanupTrash</code> / orphaned attachment cleanup) erases unreferenced private copies on disk. Uninstalling the app removes private app storage (<code>allowBackup=false</code>), while previously exported or Drive files remain where saved. Although no developer servers receive your data, User-initiated online speech, Share, and Google Drive (Google LLC) involve third-party / cross-border infrastructure subject to pre-launch legal review under KVKK Art. 9. To exercise access, rectification, erasure, or inquiry rights under KVKK Art. 11 and applicable privacy laws, contact: <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Developer: Ramazan Kocatürk","title":"İcat Defteri – Terms of Service","meta":"Last Updated: November 21, 2026 • Available features may vary by installed app version","highlight":"","sections":[["1. Parties, Scope & Release Distinction","<p>This Terms of Service (\"Agreement\") is entered into between the individual user (\"User\") of the İcat Defteri mobile application (\"Application\") and developer <strong>Ramazan Kocatürk</strong> (\"Developer\"). Alongside the local capabilities of V1.0.0, expanded V2.0 features—including real M4A audio recording, file attachments, vector sketchpad, A4 PDF project reports, and optional Google Drive backup—are governed by these terms when active in the corresponding release.</p>"],["2. Local-First Architecture & Optional Google Drive","<p>İcat Defteri operates on a local-first architecture:</p><ul><li>Notes, titles, tags, reminders, M4A audio recordings (<code>files/recordings/</code>), and file attachments (<code>files/attachments/</code>) remain solely on the User's device.</li><li>The Developer operates <strong>no</strong> proprietary cloud note database or automatic background cloud synchronization server.</li><li>Google Drive backup (<code>drive.file</code>) is strictly optional and manual; uploads occur only when the User links a Google account and initiates a backup to their own <em>İcat Defteri / Yedekler</em> Drive folder. Google Drive backup is an optional feature enabled by the user in supported app versions; available features may vary depending on the installed app version.</li></ul>"],["3. Data Loss Risk, Backup Formats & User Responsibility","<div class=\"warning-box\"><strong>IMPORTANT WARNING:</strong> Android OS automatic cloud backup is disabled (<code>allowBackup=false</code>). Losing, resetting, damaging, or uninstalling the phone may permanently erase all local data. Backups stored only inside phone storage also become inaccessible if the phone is lost—keeping a verified copy off-device is the User's responsibility.</div><ul><li><strong>Local Device Backup (.json / .zip):</strong> <em>Quick Text Backup (.json)</em> exports text/structure only and does <strong>not</strong> include M4A audio or media attachments. <em>Full Backup (.zip)</em> packages supported audio and attachments when media is enabled, or text/structure only when unchecked, in <strong>unencrypted ZIP</strong> format. Local backups are not additionally encrypted with a password by İcat Defteri.</li><li><strong>Google Drive Backup (Unencrypted ZIP):</strong> Users may manually upload text-only or media-inclusive backups to their own Google account in <strong>unencrypted ZIP</strong> format (subject to storage space, Drive quota, and connectivity). Google Drive backups are not additionally encrypted with a password by İcat Defteri.</li><li><strong>Restore Modes:</strong> <em>Merge</em> adds non-conflicting entries to existing data; <em>Overwrite</em> replaces local records after explicit confirmation (taking a fresh backup beforehand is recommended).</li></ul>"],["4. Speech Processing, File Attachments & Trash","<ul><li>Live voice dictation uses Android/Google Speech Services and saves no raw audio file.</li><li><em>Record Audio (.m4a)</em> stores recordings inside app-private storage (<code>files/recordings/</code>), not the device's public Music folder. If a recording file is missing, the note stays readable with a missing-file notice.</li><li>Photos, videos, documents (max 200 MB per file), and sketches are copied independently into <code>files/attachments/</code>; deleting the source file from Gallery leaves the note copy intact, and permanent deletion in the app does not touch the original Gallery file. Share/PDF exports create separate copies.</li></ul>"],["5. Limitation of Liability","<p>Limitations of liability apply only to the fullest extent permitted by applicable law and shall not be construed to waive mandatory statutory consumer rights. Hardware failure, device reset, accidental deletion, lack of off-device backups, or OS battery-optimization alarm delays fall outside the Developer's control. The Application is provided \"as-is\"; Google Drive and speech recognition rely on third-party service terms. Disconnecting a Google account does not delete backups already stored in Drive.</p>"],["6. Intellectual Property, Privacy & Contact","<p>Application code, interface, and branding rights belong to Ramazan Kocatürk; all ideas, notes, voice recordings, images, and attachments created by the User belong 100% to the User. Accepting this Agreement does not constitute blanket consent for optional permissions; personal data details (including Turkish KVKK Law No. 6698 notices) are set out in the Privacy Policy.<br><strong>Contact Email:</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}},"de":{"privacy":{"badge":"Transparenz- & Datenschutzhinweis","title":"İcat Defteri – Datenschutzerklärung & KVKK-Hinweis","meta":"Stand: 21. November 2026 • Verfügbare Funktionen können je nach installierter App-Version variieren","highlight":"🛡️ <strong>Grundprinzip:</strong> Der Entwickler sammelt oder speichert keine Notizen, Sprachaufnahmen oder Anhänge auf eigenen Servern. Automatische Cloud-Synchronisation und Android AutoBackup (<code>allowBackup=false</code>) sind aus; Daten verlassen das Gerät nur bei vom Nutzer gestarteter Freigabe, PDF-/Backup-Export, Online-Spracherkennung oder optionalem Google Drive (<code>drive.file</code>).","sections":[["1. Verantwortlicher & Geltungsbereich","<p>Verantwortlicher gemäß geltendem Datenschutzrecht und türkischem Gesetz Nr. 6698 (\"KVKK\") ist Entwickler <strong>Ramazan Kocatürk</strong> (<code>ramazankocaturk@gmail.com</code>). Diese Erklärung beschreibt lokale Notizen/Diktate, M4A-Audioaufnahmen, unabhängige Dateianhänge sowie das optionale, vom Nutzer freiwillig aktivierbare Google-Drive-Backup in unterstützten App-Versionen. Verfügbare Funktionen können je nach installierter App-Version variieren.</p>"],["2. Spracheingabe (Diktat) & Echte M4A-Aufnahme","<ul><li><strong>Diktat:</strong> Sprache-zu-Text läuft über Android/Google-Sprachdienste (je nach Geräteeinstellung ggf. Online-Verarbeitung durch Google). Die App speichert hierbei nur Text, kein Rohaudio.</li><li><strong>M4A-Aufnahme:</strong> Erzeugte <code>.m4a</code>-Dateien liegen privat in <code>files/recordings/</code> (nicht im gemeinsamen Musikordner). Der Entwickler hat keinen Zugriff; beim Teilen wird eine separate Kopie übertragen.</li></ul>"],["3. Lokal gespeicherte Daten & Unabhängige Kopien","<p>Titel, Notizen, Tags, Erinnerungen, Papierkorb (30 Tage), Design-/Sprach-/Sortiereinstellungen, App-Sperre (<code>BiometricPrompt</code>; keine biometrischen Vorlagen), Audios (<code>files/recordings/</code>) und Anhangkopien (<code>files/attachments/</code>, max. 200 MB) bleiben lokal. Bei verknüpftem Drive werden gewählte E-Mail und Ordner-IDs lokal in <code>SharedPreferences</code> gespeichert und beim Trennen gelöscht.</p>"],["4. Berechtigungen & Zwecke","<ul><li><strong>Mikrofon (RECORD_AUDIO):</strong> Nur bei aktiver Diktat- oder M4A-Aufnahme; kein Lauschen im Hintergrund.</li><li><strong>Benachrichtigungen / Exakte Alarme (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED):</strong> Zeigt Erinnerungen pünktlich und stellt sie nach Neustart wieder her.</li><li><strong>Kamera & Dateiauswahl (SAF):</strong> Öffnet Kamera oder Systemauswahl nur auf explizite Nutzeraktion.</li><li><strong>Netzwerk (INTERNET / ACCESS_NETWORK_STATE):</strong> Nur für Online-Spracherkennung und vom Nutzer gestartete Google-Drive-Aktionen (<code>drive.file</code>).</li></ul>"],["5. Optionales Google Drive Backup & Sicherheit","<ul><li>Nutzer können freiwillig ihr eigenes Google-Konto unter dem Scope <code>https://www.googleapis.com/auth/drive.file</code> (nur von dieser App erstellte Dateien) verbinden und bei vom Nutzer gestarteten Vorgängen Backups im <strong>ZIP-Format</strong> nach <em>Meine Ablage › İcat Defteri › Yedekler</em> übertragen.</li><li>Backups gehen ausschließlich in das Drive-Konto des Nutzers (<code>policies.google.com/privacy</code>).</li><li><strong>Medien & Verschlüsselungshinweis:</strong> Die Medienoption auf Google Drive ist standardmäßig AUS. Sowohl lokale Geräte-Backups (<code>.json</code> / <code>.zip</code>) als auch Google Drive-Backups (<code>.zip</code>) werden unverschlüsselt gespeichert und von İcat Defteri nicht zusätzlich mit einem Passwort verschlüsselt; unverschlüsselte Backups können persönliche Notizen und enthaltene Medien beinhalten.</li><li><strong>Trennen:</strong> Entfernt das lokale Sitzungstoken, ohne bereits gespeicherte Drive-Backups zu löschen.</li></ul>"],["6. Keine Analysen, Keine Werbung & Teilen","<p>Es gibt kein AdMob/Werbe-SDK, kein Firebase Analytics/Crashlytics und keine Entwickler-Accounts. <em>Teilen</em> und <em>PDF teilen</em> senden eine separate Kopie an die vom Nutzer gewählte Ziel-App; PDF-Dateien können vertrauliche Notizen enthalten.</p>"],["7. Speicherdauer, Löschung, Drittlandhinweis & Rechte (KVKK Art. 10/11)","<p>Gelöschte Einträge verbleiben 30 Tage im lokalen Papierkorb; bei endgültiger Löschung (<code>permDelete</code> / <code>cleanupTrash</code> / Bereinigung verwaister Dateien) werden nicht mehr referenzierte Kopien entfernt. Deinstallation löscht den privaten App-Speicher (<code>allowBackup=false</code>); externe Exporte und Drive-Backups bleiben erhalten. Da nutzerinitiierte Online-Spracherkennung, Teilen und Google Drive (Google LLC) Drittanbieter-/Auslandsinfrastruktur nutzen können, ist eine rechtliche Bewertung nach KVKK Art. 9 vor V2-Release vorgesehen. Für Auskunfts-, Berichtigungs-, Lösch- und Widerspruchsrechte (KVKK Art. 11 / DSGVO): <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Entwickler: Ramazan Kocatürk","title":"İcat Defteri – Nutzungsbedingungen","meta":"Stand: 21. November 2026 • Verfügbare Funktionen können je nach installierter App-Version variieren","highlight":"","sections":[["1. Vertragsparteien, Geltungsbereich & Versionen","<p>Diese Nutzungsbedingungen (\"Vereinbarung\") gelten zwischen dem jeweiligen Nutzer (\"Nutzer\") der mobilen App İcat Defteri (\"App\") und dem Entwickler <strong>Ramazan Kocatürk</strong> (\"Entwickler\"). Neben den lokalen Funktionen von V1.0.0 unterliegen die V2.0-Funktionen (echte M4A-Audioaufnahme, Dateianhänge, Zeichenbrett, PDF-Projektbericht und optionales Google-Drive-Backup) diesen Bedingungen, sobald sie in der entsprechenden Version aktiviert sind.</p>"],["2. Lokale Architektur & Optionales Google Drive","<p>İcat Defteri arbeitet lokal (local-first):</p><ul><li>Notizen, Titel, Tags, Erinnerungen, M4A-Aufnahmen (<code>files/recordings/</code>) und Dateianhänge (<code>files/attachments/</code>) verbleiben ausschließlich auf dem Gerät des Nutzers.</li><li>Der Entwickler betreibt <strong>keine</strong> eigene Cloud-Datenbank und keinen automatischen Hintergrund-Sync-Server.</li><li>Das Google-Drive-Backup (<code>drive.file</code>) ist freiwillig und manuell: Daten werden erst hochgeladen, wenn der Nutzer sein Google-Konto verbindet und eine Sicherung in seinen eigenen Ordner <em>İcat Defteri / Yedekler</em> anstößt. Die Funktion wird in unterstützten App-Versionen freiwillig vom Nutzer aktiviert; verfügbare Funktionen hängen von der installierten App-Version ab.</li></ul>"],["3. Datenverlustrisiko, Backup-Formate & Sorgfalt","<div class=\"warning-box\"><strong>WICHTIGER HINWEIS:</strong> Das automatische Android-Cloud-Backup ist deaktiviert (<code>allowBackup=false</code>). Verlust, Diebstahl, Defekt, Zurücksetzen oder Deinstallation des Geräts löschen lokale Daten dauerhaft. Eine nur im Gerätespeicher liegende Sicherung geht bei Geräteverlust ebenfalls verloren; eine externe Sicherung liegt in der Verantwortung des Nutzers.</div><ul><li><strong>Lokales Geräte-Backup (.json / .zip):</strong> <em>Schnelles Text-Backup (.json)</em> sichert nur Text und enthält <strong>keine</strong> M4A-Audios oder Medienanhänge. <em>Vollständiges Backup (.zip)</em> sichert je nach Auswahl unterstützte Medien oder nur Text im <strong>unverschlüsselten ZIP-Format</strong>. Lokale Backups werden von İcat Defteri nicht zusätzlich mit einem Passwort verschlüsselt.</li><li><strong>Google Drive-Backup (Unverschlüsseltes ZIP):</strong> Nutzer können manuelle Sicherungen mit oder ohne Medien im <strong>unverschlüsselten ZIP-Format</strong> in ihr eigenes Google-Konto übertragen (Speicherplatz, Drive-Kontingent und Internet erforderlich). Google Drive-Backups werden von İcat Defteri nicht zusätzlich mit einem Passwort verschlüsselt.</li><li><strong>Wiederherstellung:</strong> <em>Zusammenführen</em> ergänzt bestehende Daten; <em>Überschreiben</em> ersetzt lokale Bestände nach Bestätigung.</li></ul>"],["4. Sprachverarbeitung, Anhänge & Papierkorb","<ul><li>Die Live-Spracheingabe (Diktat) nutzt Android/Google-Sprachdienste ohne Speicherung von Rohaudio.</li><li><em>Audio aufnehmen (.m4a)</em> speichert Dateien nicht im öffentlichen Musikordner, sondern geschützt in <code>files/recordings/</code>. Fehlt eine Datei, bleibt der Notiztext mit Hinweis erhalten.</li><li>Fotos, Videos, Dokumente (max. 200 MB pro Datei) und Zeichnungen werden als unabhängige Kopien in <code>files/attachments/</code> abgelegt: Das Löschen aus der Galerie lässt die Notizkopie unberührt, und dauerhaftes Löschen in der App berührt das Original nicht. Teilen/PDF-Export erzeugt eigene Kopien.</li></ul>"],["5. Haftungsbeschränkung","<p>Haftungsbeschränkungen gelten nur im gesetzlich zulässigen Rahmen und schränken zwingende Verbraucherrechte nicht ein. Gerätedefekte, Reset, fehlende externe Backups oder akkusparbedingte Alarmverzögerungen liegen außerhalb der Kontrolle des Entwicklers. Die App wird \"wie besehen\" bereitgestellt; Google Drive und Sprachdienste unterliegen Drittanbieterbedingungen. Das Trennen des Google-Kontos löscht bestehende Drive-Sicherungen nicht.</p>"],["6. Geistiges Eigentum, Datenschutz & Kontakt","<p>Code, Oberfläche und Markenrechte gehören Ramazan Kocatürk; sämtliche vom Nutzer erstellten Ideen, Texte, Sprachaufnahmen und Dateien gehören dem Nutzer. Die Zustimmung zu diesen Bedingungen ersetzt keine gesonderte Einwilligung für optionale Berechtigungen; Details (einschließlich KVKK Nr. 6698) regelt die Datenschutzerklärung.<br><strong>Kontakt:</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}},"fr":{"privacy":{"badge":"Notice de Transparence & Sécurité des Données","title":"İcat Defteri – Politique de Confidentialité & KVKK","meta":"Mise à jour : 21 novembre 2026 • Les fonctionnalités disponibles peuvent varier selon la version installée","highlight":"🛡️ <strong>Principe Fondamental :</strong> Le Développeur ne collecte ni n'héberge les notes, audios ou pièces jointes sur aucun serveur personnel. Aucune synchronisation cloud automatique ni AutoBackup Android (<code>allowBackup=false</code>) ; aucune donnée ne quitte l'appareil sauf Partage, export PDF/Archive, dictée vocale système ou sauvegarde Google Drive facultative (<code>drive.file</code>).","sections":[["1. Responsable du Traitement et Portée","<p>Le responsable du traitement au titre des lois applicables et de la loi turque n° 6698 (« KVKK ») est le développeur <strong>Ramazan Kocatürk</strong> (<code>ramazankocaturk@gmail.com</code>). Cette notice couvre les notes/dictées locales, l'enregistrement audio M4A, les pièces jointes indépendantes et la sauvegarde Google Drive optionnelle activée librement par l'utilisateur dans les versions prises en charge. Les fonctionnalités disponibles peuvent varier selon la version installée.</p>"],["2. Dictée Vocale vs Enregistrement Audio M4A","<ul><li><strong>Dictée Vocale :</strong> La transcription utilise les services vocaux Android/Google (pouvant traiter l'audio en ligne selon les réglages du téléphone) ; aucun audio brut n'est conservé par l'Application.</li><li><strong>Enregistrement M4A réel :</strong> Les fichiers <code>.m4a</code> sont enregistrés exclusivement dans <code>files/recordings/</code> (hors dossier public Musique). Le Développeur n'y a pas accès ; le partage envoie une copie distincte.</li></ul>"],["3. Données Locales & Copies Indépendantes","<p>Titres, notes, étiquettes, rappels, Corbeille (30 jours), préférences (thème, langue, tri), verrouillage (<code>BiometricPrompt</code> ; aucune donnée biométrique collectée), audios (<code>files/recordings/</code>) et copies de pièces jointes (<code>files/attachments/</code>, max 200 Mo/fichier) restent sur l'appareil. Lorsque Drive est connecté, l'adresse choisie et les identifiants de dossier sont stockés localement dans <code>SharedPreferences</code> et effacés à la déconnexion.</p>"],["4. Autorisations Utilisées et Finalités","<ul><li><strong>Microphone (RECORD_AUDIO) :</strong> Uniquement sur action de dictée ou d'enregistrement M4A ; aucune écoute en arrière-plan.</li><li><strong>Notifications / Alarmes Exactes (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED) :</strong> Affiche les rappels à l'heure et les reprogramme après redémarrage.</li><li><strong>Appareil Photo & Sélecteur de Fichiers (SAF) :</strong> Ouvre la caméra ou le sélecteur système uniquement sur clic de l'Utilisateur.</li><li><strong>Réseau (INTERNET / ACCESS_NETWORK_STATE) :</strong> Uniquement pour la dictée en ligne et les transferts Google Drive (<code>drive.file</code>) initiés par l'Utilisateur.</li></ul>"],["5. Sauvegarde Google Drive Facultative & Sécurité","<ul><li>L'Utilisateur peut lier son propre compte Google via la portée minimale <code>https://www.googleapis.com/auth/drive.file</code> (limitée aux fichiers créés par cette application) pour transférer, à sa propre initiative, des sauvegardes au format <strong>ZIP</strong> vers <em>Mon Drive › İcat Defteri › Yedekler</em>.</li><li>Les fichiers restent dans le Drive personnel de l'Utilisateur (<code>policies.google.com/privacy</code>).</li><li><strong>Médias & Information sur le Chiffrement :</strong> L'option médias sur Google Drive est désactivée par défaut. Les sauvegardes locales (<code>.json</code> / <code>.zip</code>) comme les sauvegardes Google Drive (<code>.zip</code>) sont enregistrées sans chiffrement supplémentaire par mot de passe par İcat Defteri ; ces fichiers peuvent contenir vos notes personnelles et les médias inclus.</li><li><strong>Déconnexion :</strong> Révoque le jeton de session local sans supprimer les sauvegardes existantes sur Drive.</li></ul>"],["6. Analytique, Publicité et Partage","<p>Aucun SDK publicitaire (AdMob), aucun suivi analytique (Firebase Analytics/Crashlytics) et aucun serveur utilisateur central. <em>Partager</em> et <em>Partager PDF</em> transmettent une copie distincte à l'application cible choisie ; les PDF peuvent contenir des notes sensibles.</p>"],["7. Conservation, Suppression, Transferts & Droits (KVKK Art. 10/11)","<p>Les éléments supprimés restent 30 jours dans la Corbeille ; la suppression définitive (<code>permDelete</code> / <code>cleanupTrash</code> / nettoyage orphelin) efface les copies privées non référencées. La désinstallation efface le stockage privé (<code>allowBackup=false</code>) tout en laissant intacts les exports externes et sauvegardes Drive. Les flux tiers déclenchés par l'Utilisateur (dictée, Partage, Google Drive / Google LLC) font l'objet d'une évaluation juridique de transfert international (KVKK art. 9) avant lancement de la V2. Contact pour exercer vos droits (KVKK art. 11 / RGPD) : <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Développeur : Ramazan Kocatürk","title":"İcat Defteri – Conditions d'Utilisation","meta":"Mise à jour : 21 novembre 2026 • Les fonctionnalités disponibles peuvent varier selon la version installée","highlight":"","sections":[["1. Parties, Portée et Distinction de Version","<p>Les présentes Conditions d'Utilisation (« Accord ») sont conclues entre l'utilisateur (« Utilisateur ») de l'application mobile İcat Defteri (« Application ») et le développeur <strong>Ramazan Kocatürk</strong> (« Développeur »). Outre les fonctions locales de la V1.0.0, les nouveautés V2.0 (audio M4A réel, pièces jointes, dessin vectoriel, rapport PDF A4 et sauvegarde Google Drive facultative) sont régies par cet accord dès leur activation.</p>"],["2. Architecture Locale et Google Drive Facultatif","<p>İcat Defteri fonctionne en priorité en local (local-first) :</p><ul><li>Notes, titres, étiquettes, rappels, enregistrements M4A (<code>files/recordings/</code>) et pièces jointes (<code>files/attachments/</code>) restent uniquement sur l'appareil de l'Utilisateur.</li><li>Le Développeur n'exploite <strong>aucune</strong> base cloud ni serveur de synchronisation automatique en arrière-plan.</li><li>La sauvegarde Google Drive (<code>drive.file</code>) est facultative et manuelle : le transfert n'a lieu que lorsque l'Utilisateur connecte son compte Google vers son dossier <em>İcat Defteri / Yedekler</em>. Cette fonction est activée librement par l'utilisateur dans les versions prises en charge ; les fonctionnalités disponibles varient selon la version installée.</li></ul>"],["3. Risque de Perte, Formats & Responsabilité","<div class=\"warning-box\"><strong>AVERTISSEMENT IMPORTANT :</strong> La sauvegarde cloud automatique Android est désactivée (<code>allowBackup=false</code>). En cas de perte, vol, panne, réinitialisation ou désinstallation, toutes les données locales peuvent être supprimées définitivement. Une sauvegarde conservée uniquement sur le téléphone est perdue avec l'appareil ; conserver une copie externe vérifiée relève de l'Utilisateur.</div><ul><li><strong>Sauvegarde Locale (.json / .zip) :</strong> <em>Sauvegarde Texte Rapide (.json)</em> exporte uniquement le texte et <strong>n'inclut pas</strong> les audios M4A ni les médias. <em>Sauvegarde Complète (.zip)</em> emballe les médias pris en charge ou le texte seul au format <strong>ZIP non chiffré</strong>. Les sauvegardes locales ne sont pas chiffrées en plus par mot de passe par İcat Defteri.</li><li><strong>Sauvegarde Google Drive (ZIP non chiffré) :</strong> L'Utilisateur peut transférer manuellement sur son propre compte Google des sauvegardes avec ou sans médias au format <strong>ZIP non chiffré</strong> (selon espace, quota Drive et connexion). Les sauvegardes Google Drive ne sont pas chiffrées en plus par mot de passe par İcat Defteri.</li><li><strong>Restauration :</strong> <em>Fusionner</em> ajoute les nouveaux éléments ; <em>Écraser</em> remplace les données locales après confirmation.</li></ul>"],["4. Traitement Vocal, Pièces Jointes et Corbeille","<ul><li>La dictée vocale utilise les services vocaux Android/Google sans enregistrer d'audio brut.</li><li><em>Enregistrer l'audio (.m4a)</em> enregistre dans l'espace privé <code>files/recordings/</code> et jamais dans le dossier public Musique. Si le fichier manque, la note reste lisible avec un avertissement.</li><li>Photos, vidéos, documents (max 200 Mo/fichier) et dessins sont copiés de manière indépendante dans <code>files/attachments/</code> : supprimer le fichier original de la Galerie conserve la copie dans la note, et la suppression définitive dans l'app n'affecte pas la Galerie. Partage/PDF génère une copie séparée.</li></ul>"],["5. Limitation de Responsabilité","<p>Toute limitation de responsabilité s'applique uniquement dans la mesure permise par la loi et n'écarte aucun droit impératif du consommateur. Pannes matérielles, réinitialisation, perte d'appareil ou retards d'alarme dus à l'économie de batterie échappent au contrôle du Développeur. L'Application est fournie « en l'état » ; Google Drive et la dictée relèvent des conditions de tiers. Déconnecter le compte Google ne supprime pas les sauvegardes déjà présentes sur Drive.</p>"],["6. Propriété Intellectuelle, Confidentialité & Contact","<p>Le code, l'interface et la marque appartiennent à Ramazan Kocatürk ; tous les contenus créés par l'Utilisateur (idées, notes, audios, images) lui appartiennent intégralement. L'acceptation de cet Accord ne vaut pas consentement illimité aux autorisations facultatives ; les détails (dont KVKK n° 6698) figurent dans la Politique de Confidentialité.<br><strong>E-mail :</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}},"es":{"privacy":{"badge":"Aviso de Transparencia y Seguridad de Datos","title":"İcat Defteri – Política de Privacidad y Aviso KVKK","meta":"Actualización: 21 de noviembre de 2026 • Las funciones disponibles pueden variar según la versión instalada","highlight":"🛡️ <strong>Principio Fundamental:</strong> El Desarrollador no recopila ni aloja notas, grabaciones ni archivos en servidores propios. Sin sincronización automática ni Android AutoBackup (<code>allowBackup=false</code>); los datos no salen del dispositivo salvo al Compartir, exportar PDF/Copia, dictado por voz de Google o Google Drive opcional (<code>drive.file</code>).","sections":[["1. Responsable y Alcance","<p>El responsable del tratamiento conforme a la normativa aplicable y la Ley Turca KVKK n.º 6698 es el desarrollador <strong>Ramazan Kocatürk</strong> (<code>ramazankocaturk@gmail.com</code>). Este documento describe las notas/dictado locales, la grabación M4A, los adjuntos independientes y la copia de seguridad opcional en Google Drive activada voluntariamente por el usuario en las versiones compatibles. Las funciones disponibles pueden variar según la versión instalada.</p>"],["2. Dictado por Voz vs. Grabación M4A","<ul><li><strong>Dictado por Voz:</strong> Convierte voz a texto mediante Android/Google Speech Services (puede procesarse en línea según ajustes del móvil); la App solo guarda texto.</li><li><strong>Grabación M4A real:</strong> Los archivos <code>.m4a</code> se guardan únicamente en <code>files/recordings/</code> (fuera de la carpeta pública Música). El Desarrollador no tiene acceso; al compartir se envía una copia distinta.</li></ul>"],["3. Datos Locales y Copias Independientes","<p>Títulos, notas, etiquetas, recordatorios, Papelera (30 días), preferencias (tema, idioma, orden), bloqueo biométrico (<code>BiometricPrompt</code>; nunca se acceden plantillas biométricas), audios (<code>files/recordings/</code>) y copias de adjuntos (<code>files/attachments/</code>, máx. 200 MB/archivo) permanecen locales. Con Drive conectado, el correo elegido y los IDs de carpeta se guardan en <code>SharedPreferences</code> y se borran al desconectar.</p>"],["4. Permisos y Finalidades","<ul><li><strong>Micrófono (RECORD_AUDIO):</strong> Solo al pulsar dictado o grabación M4A; sin escucha en segundo plano.</li><li><strong>Notificaciones / Alarmas Exactas (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED):</strong> Muestra recordatorios puntualmente y los reprograma tras reiniciar.</li><li><strong>Cámara y Selector de Archivos (SAF):</strong> Abre cámara o selector del sistema solo por acción del Usuario.</li><li><strong>Red (INTERNET / ACCESS_NETWORK_STATE):</strong> Solo para reconocimiento de voz en línea y transferencias voluntarias a Google Drive (<code>drive.file</code>).</li></ul>"],["5. Copia Opcional en Google Drive y Seguridad","<ul><li>El Usuario puede vincular voluntariamente su cuenta Google bajo el alcance mínimo <code>https://www.googleapis.com/auth/drive.file</code> (solo archivos creados por esta app) para transferir, por acción iniciada por el Usuario, copias en formato <strong>ZIP</strong> a <em>Mi unidad › İcat Defteri › Yedekler</em>.</li><li>Las copias van a su propio Google Drive bajo las políticas de Google (<code>policies.google.com/privacy</code>).</li><li><strong>Multimedia y Aviso de Cifrado:</strong> La opción multimedia en Google Drive viene desactivada por defecto. Tanto las copias locales (<code>.json</code> / <code>.zip</code>) como las copias de Google Drive (<code>.zip</code>) se guardan sin cifrado adicional con contraseña por parte de İcat Defteri; estos archivos pueden contener notas personales y los medios incluidos.</li><li><strong>Desconexión:</strong> Limpia el token local sin borrar copias ya almacenadas en Drive.</li></ul>"],["6. Analíticas, Publicidad y Compartición","<p>No hay SDKs de publicidad (AdMob), ni seguimiento analítico (Firebase Analytics/Crashlytics) ni servidores de cuentas. <em>Compartir</em> y <em>Compartir PDF</em> envían una copia separada a la app que elijas; los PDF pueden incluir notas sensibles.</p>"],["7. Conservación, Eliminación, Transferencias y Derechos (KVKK Art. 10/11)","<p>Los elementos eliminados permanecen 30 días en Papelera; el borrado definitivo (<code>permDelete</code> / <code>cleanupTrash</code> / limpieza huérfana) elimina copias privadas sin referencias. Desinstalar borra el área privada (<code>allowBackup=false</code>) pero conserva exportaciones externas y archivos en Drive. Dado que dictado en línea, Compartir y Google Drive (Google LLC) involucran infraestructura externa/internacional iniciada por el Usuario, el aspecto de transferencia transfronteriza (KVKK art. 9) se evalúa antes del lanzamiento V2. Contacto para ejercer derechos (KVKK art. 11 / RGPD): <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Desarrollador: Ramazan Kocatürk","title":"İcat Defteri – Términos de Servicio","meta":"Actualización: 21 de noviembre de 2026 • Las funciones disponibles pueden variar según la versión instalada","highlight":"","sections":[["1. Partes, Alcance y Distinción de Versiones","<p>Estos Términos de Servicio («Acuerdo») se celebran entre el usuario («Usuario») de la aplicación móvil İcat Defteri («Aplicación») y el desarrollador <strong>Ramazan Kocatürk</strong> («Desarrollador»). Junto con las funciones locales de la V1.0.0, las funciones V2.0 (grabación M4A real, adjuntos, dibujo vectorial, informe PDF A4 y copia opcional en Google Drive) se rigen por este Acuerdo cuando están activas en su versión.</p>"],["2. Arquitectura Local y Google Drive Opcional","<p>İcat Defteri funciona con prioridad local (local-first):</p><ul><li>Notas, títulos, etiquetas, recordatorios, audios M4A (<code>files/recordings/</code>) y adjuntos (<code>files/attachments/</code>) permanecen exclusivamente en el dispositivo del Usuario.</li><li>El Desarrollador no mantiene <strong>ninguna</strong> base de datos en la nube ni servidor de sincronización automática en segundo plano.</li><li>La copia en Google Drive (<code>drive.file</code>) es opcional y manual: solo sube archivos cuando el Usuario vincula su cuenta Google a su propia carpeta <em>İcat Defteri / Yedekler</em>. Esta función es activada opcionalmente por el usuario en las versiones compatibles; las funciones disponibles varían según la versión instalada.</li></ul>"],["3. Riesgo de Pérdida, Formatos y Responsabilidad","<div class=\"warning-box\"><strong>ADVERTENCIA IMPORTANTE:</strong> La copia automática en la nube de Android está desactivada (<code>allowBackup=false</code>). En caso de pérdida, robo, avería, restablecimiento o desinstalación, los datos locales pueden eliminarse permanentemente. Una copia guardada solo en el mismo teléfono también se pierde con él; conservar una copia verificada externa es responsabilidad del Usuario.</div><ul><li><strong>Copia Local (.json / .zip):</strong> <em>Copia Rápida de Texto (.json)</em> solo exporta texto y <strong>no</strong> incluye audios M4A ni multimedia. <em>Copia Completa (.zip)</em> empaqueta medios compatibles o solo texto en formato <strong>ZIP sin cifrar</strong>. İcat Defteri no cifra adicionalmente con contraseña las copias locales.</li><li><strong>Copia en Google Drive (ZIP sin cifrar):</strong> El Usuario puede subir manualmente a su propia cuenta Google copias con o sin medios en formato <strong>ZIP sin cifrar</strong> (requiere espacio libre, cuota y red). İcat Defteri no cifra adicionalmente con contraseña las copias de Google Drive.</li><li><strong>Restauración:</strong> <em>Combinar</em> agrega elementos nuevos; <em>Sobrescribir</em> reemplaza los datos locales tras confirmar.</li></ul>"],["4. Voz, Archivos Adjuntos y Papelera","<ul><li>El dictado por voz usa Servicios de Voz de Android/Google sin guardar audio sin procesar.</li><li><em>Grabar Audio (.m4a)</em> guarda en almacenamiento privado (<code>files/recordings/</code>), nunca en la carpeta pública Música. Si falta el audio, la nota sigue legible con aviso.</li><li>Fotos, vídeos, documentos (límite 200 MB/archivo) y dibujos se copian independientemente en <code>files/attachments/</code>: borrar el original en Galería mantiene la copia en la nota, y eliminarla definitivamente en la app no toca el archivo original. Compartir/PDF crea una copia separada.</li></ul>"],["5. Limitación de Responsabilidad","<p>Cualquier limitación aplica únicamente en la medida permitida por la ley y no suprime derechos irrenunciables del consumidor. Fallos del dispositivo, restablecimiento, falta de copia externa o retrasos de alarmas por ahorro de batería están fuera del control del Desarrollador. La App se ofrece «tal cual»; Google Drive y dictado dependen de términos de terceros. Desconectar la cuenta Google no borra copias ya guardadas en Drive.</p>"],["6. Propiedad Intelectual, Privacidad y Contacto","<p>El código, diseño y marca pertenecen a Ramazan Kocatürk; todo contenido creado por el Usuario (ideas, notas, audios, archivos) es 100% suyo. Aceptar este Acuerdo no implica consentimiento amplio para permisos opcionales; los detalles de datos personales (incluida KVKK n.º 6698) figuran en la Política de Privacidad.<br><strong>Correo:</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}},"it":{"privacy":{"badge":"Informativa sulla Trasparenza e Sicurezza Dati","title":"İcat Defteri – Informativa sulla Privacy e KVKK","meta":"Aggiornamento: 21 novembre 2026 • Le funzionalità disponibili possono variare in base alla versione installata","highlight":"🛡️ <strong>Principio Fondamentale:</strong> Lo Sviluppatore non raccoglie né ospita note, audio o allegati su server propri. Nessuna sincronizzazione cloud automatica né Android AutoBackup (<code>allowBackup=false</code>); i dati restano sul dispositivo salvo Condivisione, export PDF/Archivio, dettatura vocale Google o backup volontario su Google Drive (<code>drive.file</code>).","sections":[["1. Titolare del Trattamento e Ambito","<p>Il titolare ai sensi della legge applicabile e della legge turca KVKK n. 6698 è lo sviluppatore <strong>Ramazan Kocatürk</strong> (<code>ramazankocaturk@gmail.com</code>). Il testo copre note/dettatura locali, registrazione M4A, allegati indipendenti e il backup opzionale su Google Drive attivato volontariamente dall'utente nelle versioni supportate. Le funzionalità disponibili possono variare in base alla versione installata.</p>"],["2. Dettatura Vocale vs Registrazione M4A","<ul><li><strong>Dettatura Vocale:</strong> Converte voce in testo tramite Android/Google Speech Services (può elaborare online in base alle impostazioni); l'App conserva solo testo.</li><li><strong>Registrazione M4A reale:</strong> I file <code>.m4a</code> vengono salvati esclusivamente in <code>files/recordings/</code> (mai nella cartella Musica). Lo Sviluppatore non vi accede; condividendo si invia una copia separata.</li></ul>"],["3. Dati Locali e Copie Indipendenti","<p>Titoli, note, tag, promemoria, Cestino (30 giorni), preferenze (tema, lingua, ordine), blocco app (<code>BiometricPrompt</code>; nessun dato biometrico raccolto), audio (<code>files/recordings/</code>) e copie degli allegati (<code>files/attachments/</code>, max 200 MB/file) restano locali. Con Drive collegato, e-mail scelta e ID cartella restano in <code>SharedPreferences</code> e vengono cancellati alla disconnessione.</p>"],["4. Permessi e Finalità","<ul><li><strong>Microfono (RECORD_AUDIO):</strong> Solo su avvio di dettatura o registrazione M4A; nessun ascolto in background.</li><li><strong>Notifiche / Sveglie Esatte (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED):</strong> Mostra promemoria puntuali e li ripristina al riavvio.</li><li><strong>Fotocamera & Selettore File (SAF):</strong> Apre fotocamera o selettore di sistema solo su azione dell'Utente.</li><li><strong>Rete (INTERNET / ACCESS_NETWORK_STATE):</strong> Solo per dettatura online e trasferimenti volontari su Google Drive (<code>drive.file</code>).</li></ul>"],["5. Backup Opzionale su Google Drive & Sicurezza","<ul><li>L'Utente può collegare il proprio account Google tramite l'ambito minimo <code>https://www.googleapis.com/auth/drive.file</code> (solo file creati dall'app) per trasferire, su azione avviata dall'Utente, backup in formato <strong>ZIP</strong> nella cartella <em>Il mio Drive › İcat Defteri › Yedekler</em>.</li><li>I backup risiedono solo nel Drive personale dell'Utente (<code>policies.google.com/privacy</code>).</li><li><strong>Media e Nota sulla Cifratura:</strong> L'opzione media su Google Drive è disattivata per impostazione predefinita. Sia i backup locali (<code>.json</code> / <code>.zip</code>) sia i backup su Google Drive (<code>.zip</code>) sono salvati senza ulteriore crittografia con password da parte di İcat Defteri; tali file possono contenere note personali e gli eventuali media inclusi.</li><li><strong>Scollegamento:</strong> Rimuove la sessione locale senza cancellare i backup già su Drive.</li></ul>"],["6. Analisi, Pubblicità e Condivisione","<p>Nessun SDK pubblicitario (AdMob), nessun tracciamento analitico (Firebase Analytics/Crashlytics) né server di account. <em>Condividi</em> e <em>Condividi PDF</em> inviano una copia separata all'app scelta; i PDF possono contenere dati sensibili.</p>"],["7. Conservazione, Cancellazione, Trasferimenti e Diritti (KVKK Art. 10/11)","<p>Gli elementi eliminati restano 30 giorni nel Cestino; l'eliminazione definitiva (<code>permDelete</code> / <code>cleanupTrash</code> / pulizia orfani) rimuove le copie private non più usate. Disinstallando l'app si cancella l'area privata (<code>allowBackup=false</code>), lasciando intatti export esterni e Drive. Poiché dettatura online, Condividi e Google Drive (Google LLC) attivati dall'Utente possono implicare infrastrutture estere, il profilo di trasferimento (KVKK art. 9) è oggetto di verifica legale pre-rilascio V2. Contatto per i diritti (KVKK art. 11 / GDPR): <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Sviluppatore: Ramazan Kocatürk","title":"İcat Defteri – Termini di Servizio","meta":"Aggiornamento: 21 novembre 2026 • Le funzionalità disponibili possono variare in base alla versione installata","highlight":"","sections":[["1. Parti, Ambito e Distinzione di Versione","<p>I presenti Termini di Servizio («Accordo») regolano l'uso dell'app İcat Defteri («Applicazione») tra l'utente («Utente») e lo sviluppatore <strong>Ramazan Kocatürk</strong> («Sviluppatore»). Oltre alle funzioni locali della V1.0.0, le novità V2.0 (registrazione audio M4A reale, allegati, disegno vettoriale, report PDF A4 e backup opzionale su Google Drive) sono soggette a questi termini quando attive nella relativa versione.</p>"],["2. Architettura Locale e Google Drive Opzionale","<p>İcat Defteri opera con priorità locale (local-first):</p><ul><li>Note, titoli, tag, promemoria, registrazioni M4A (<code>files/recordings/</code>) e allegati (<code>files/attachments/</code>) restano solo sul dispositivo dell'Utente.</li><li>Lo Sviluppatore non gestisce <strong>alcun</strong> database cloud né server di sincronizzazione automatica in background.</li><li>Il backup su Google Drive (<code>drive.file</code>) è facoltativo e manuale: avviene solo se l'Utente collega il proprio account Google verso la cartella <em>İcat Defteri / Yedekler</em>. La funzione è attivata facoltativamente dall'utente nelle versioni supportate; le funzionalità disponibili variano in base alla versione installata.</li></ul>"],["3. Rischio Perdita Dati, Formati e Responsabilità","<div class=\"warning-box\"><strong>AVVISO IMPORTANTE:</strong> Il backup automatico cloud di Android è disabilitato (<code>allowBackup=false</code>). Smarrimento, furto, guasto, ripristino o disinstallazione possono cancellare definitivamente tutti i dati locali. Anche i backup salvati solo sul telefono risultano inaccessibili se il dispositivo si perde; conservare una copia esterna verificata spetta all'Utente.</div><ul><li><strong>Backup Locale (.json / .zip):</strong> <em>Backup Rapido di Testo (.json)</em> esporta solo testo e <strong>non</strong> include audio M4A né allegati multimediali. <em>Backup Completo (.zip)</em> include media compatibili o solo testo in formato <strong>ZIP non crittografato</strong>. I backup locali non vengono ulteriormente crittografati con password da İcat Defteri.</li><li><strong>Backup Google Drive (ZIP non crittografato):</strong> L'Utente può trasferire manualmente sul proprio account Google backup con o senza media in formato <strong>ZIP non crittografato</strong> (richiede spazio, quota e rete). I backup su Google Drive non vengono ulteriormente crittografati con password da İcat Defteri.</li><li><strong>Ripristino:</strong> <em>Unisci</em> aggiunge nuovi elementi; <em>Sovrascrivi</em> sostituisce i dati locali previa conferma.</li></ul>"],["4. Voce, Allegati e Cestino","<ul><li>La dettatura usa i servizi vocali Android/Google senza salvare audio grezzo.</li><li><em>Registra Audio (.m4a)</em> salva nello spazio privato <code>files/recordings/</code>, mai nella cartella pubblica Musica. Se il file manca, la nota resta leggibile con avviso.</li><li>Foto, video, documenti (limite 200 MB/file) e disegni sono copiati indipendentemente in <code>files/attachments/</code>: rimuovere l'originale dalla Galleria lascia intatta la copia nella nota, e l'eliminazione definitiva in app non tocca la Galleria. Condividi/PDF genera una copia separata.</li></ul>"],["5. Limitazione di Responsabilità","<p>Le limitazioni si applicano nei limiti consentiti dalla legge e non pregiudicano i diritti irrinunciabili dei consumatori. Guasti, reset, mancato backup esterno o ritardi delle sveglie per risparmio energetico esulano dal controllo dello Sviluppatore. L'App è fornita «così com'è»; Google Drive e dettatura seguono i termini di terze parti. Scollegare l'account Google non cancella i backup già su Drive.</p>"],["6. Proprietà Intellettuale, Privacy e Contatti","<p>Codice, interfaccia e marchio spettano a Ramazan Kocatürk; tutti i contenuti creati dall'Utente restano al 100% di sua proprietà. L'accettazione di questi Termini non equivale a consenso generico per permessi opzionali; i dettagli sui dati personali (inclusa KVKK n. 6698) sono nell'Informativa sulla Privacy.<br><strong>E-mail:</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}},"pt":{"privacy":{"badge":"Aviso de Transparência e Segurança de Dados","title":"İcat Defteri – Política de Privacidade e Aviso KVKK","meta":"Atualização: 21 de novembro de 2026 • Os recursos disponíveis podem variar conforme a versão instalada","highlight":"🛡️ <strong>Princípio Fundamental:</strong> O Desenvolvedor não coleta nem hospeda notas, áudios ou anexos em servidores próprios. Não há sincronização automática nem Android AutoBackup (<code>allowBackup=false</code>); dados só saem do aparelho por Compartilhamento, exportação PDF/Arquivo, ditado Google ou backup opcional no Google Drive (<code>drive.file</code>).","sections":[["1. Controlador e Escopo","<p>O controlador nos termos da legislação aplicável e da Lei Turca KVKK n.º 6698 é o desenvolvedor <strong>Ramazan Kocatürk</strong> (<code>ramazankocaturk@gmail.com</code>). Este aviso abrange notas/ditado locais, gravação M4A, anexos independentes e o backup opcional no Google Drive ativado voluntariamente pelo usuário nas versões compatíveis. Os recursos disponíveis podem variar conforme a versão instalada.</p>"],["2. Ditado por Voz vs. Gravação M4A","<ul><li><strong>Ditado por Voz:</strong> Converte fala em texto via Android/Google Speech Services (podendo ser processado online conforme ajustes do aparelho); o app mantém apenas texto.</li><li><strong>Gravação M4A real:</strong> Arquivos <code>.m4a</code> ficam exclusivamente em <code>files/recordings/</code> (nunca na pasta pública Música). O Desenvolvedor não tem acesso; ao compartilhar é enviada cópia separada.</li></ul>"],["3. Dados Locais e Cópias Independentes","<p>Títulos, notas, tags, lembretes, Lixeira (30 dias), preferências (tema, idioma, ordem), bloqueio biométrico (<code>BiometricPrompt</code>; modelos biométricos nunca são coletados), áudios (<code>files/recordings/</code>) e cópias de anexos (<code>files/attachments/</code>, máx. 200 MB/arquivo) ficam locais. Com o Drive conectado, e-mail e IDs de pasta ficam em <code>SharedPreferences</code> e são apagados ao desconectar.</p>"],["4. Permissões e Finalidades","<ul><li><strong>Microfone (RECORD_AUDIO):</strong> Apenas quando o Usuário inicia ditado ou gravação M4A; sem escuta em segundo plano.</li><li><strong>Notificações / Alarmes Exatos (POST_NOTIFICATIONS, SCHEDULE_EXACT_ALARM, WAKE_LOCK, BOOT_COMPLETED):</strong> Exibe lembretes no horário e os reagenda após reiniciar.</li><li><strong>Câmera e Seletor de Arquivos (SAF):</strong> Abre câmera ou seletor do sistema somente por ação do Usuário.</li><li><strong>Rede (INTERNET / ACCESS_NETWORK_STATE):</strong> Apenas para ditado online e transferências voluntárias ao Google Drive (<code>drive.file</code>).</li></ul>"],["5. Backup Opcional no Google Drive e Segurança","<ul><li>O Usuário pode vincular sua conta Google pelo escopo mínimo <code>https://www.googleapis.com/auth/drive.file</code> (restrito aos arquivos criados pelo app) para transferir, mediante ação iniciada pelo Usuário, backups em formato <strong>ZIP</strong> para <em>Meu Drive › İcat Defteri › Yedekler</em>.</li><li>Backups vão somente ao Drive pessoal do Usuário (<code>policies.google.com/privacy</code>).</li><li><strong>Mídia e Aviso de Criptografia:</strong> A opção de mídia no Google Drive inicia desmarcada. Tanto os backups locais (<code>.json</code> / <code>.zip</code>) quanto os backups no Google Drive (<code>.zip</code>) são salvos sem criptografia adicional com senha pelo İcat Defteri; esses arquivos podem conter notas pessoais e os arquivos de mídia incluídos.</li><li><strong>Desconexão:</strong> Remove o token local sem apagar backups já salvos no Drive.</li></ul>"],["6. Análises, Publicidade e Compartilhamento","<p>Zero SDKs de anúncios (AdMob), zero rastreamento analítico (Firebase Analytics/Crashlytics) e zero servidores de contas. <em>Compartilhar</em> e <em>Compartilhar PDF</em> enviam cópia separada ao app escolhido; PDFs podem conter notas sensíveis.</p>"],["7. Retenção, Exclusão, Transferências e Direitos (KVKK Art. 10/11)","<p>Itens excluídos permanecem 30 dias na Lixeira; a exclusão permanente (<code>permDelete</code> / <code>cleanupTrash</code> / limpeza de órfãos) apaga cópias privadas não referenciadas. Desinstalar apaga o armazenamento privado (<code>allowBackup=false</code>) sem afetar exportações externas nem o Drive. Como ditado online, Compartilhamento e Google Drive (Google LLC) envolvem infraestrutura externa iniciada pelo Usuário, o aspecto de transferência internacional (KVKK art. 9) passa por revisão jurídica pré-lançamento V2. Contato para direitos (KVKK art. 11 / LGPD / GDPR): <strong>ramazankocaturk@gmail.com</strong>.</p>"]]},"terms":{"badge":"Desenvolvedor: Ramazan Kocatürk","title":"İcat Defteri – Termos de Serviço","meta":"Atualização: 21 de novembro de 2026 • Os recursos disponíveis podem variar conforme a versão instalada","highlight":"","sections":[["1. Partes, Escopo e Distinção de Versão","<p>Estes Termos de Serviço («Acordo») são celebrados entre o usuário («Usuário») do aplicativo İcat Defteri («Aplicativo») e o desenvolvedor <strong>Ramazan Kocatürk</strong> («Desenvolvedor»). Além dos recursos locais da V1.0.0, as novidades da V2.0 (gravação M4A real, anexos, desenho vetorial, relatório PDF A4 e backup opcional no Google Drive) seguem este Acordo quando ativos na versão correspondente.</p>"],["2. Arquitetura Local e Google Drive Opcional","<p>O İcat Defteri opera em arquitetura local-first:</p><ul><li>Notas, títulos, tags, lembretes, áudios M4A (<code>files/recordings/</code>) e anexos (<code>files/attachments/</code>) permanecem apenas no dispositivo do Usuário.</li><li>O Desenvolvedor <strong>não</strong> mantém banco em nuvem nem servidor de sincronização automática em segundo plano.</li><li>O backup no Google Drive (<code>drive.file</code>) é opcional e manual: só ocorre quando o Usuário conecta sua conta Google à sua própria pasta <em>İcat Defteri / Yedekler</em>. Esse recurso é ativado opcionalmente pelo usuário nas versões compatíveis; os recursos disponíveis variam conforme a versão instalada.</li></ul>"],["3. Risco de Perda, Formatos e Responsabilidade","<div class=\"warning-box\"><strong>AVISO IMPORTANTE:</strong> O backup automático em nuvem do Android é desativado (<code>allowBackup=false</code>). Perda, roubo, defeito, restauração de fábrica ou desinstalação apagam definitivamente os dados locais. Backups salvos apenas no mesmo aparelho também se perdem com ele; manter uma cópia verificada fora do aparelho é responsabilidade do Usuário.</div><ul><li><strong>Backup Local (.json / .zip):</strong> <em>Backup Rápido de Texto (.json)</em> exporta apenas texto e <strong>não</strong> inclui áudios M4A nem mídia. <em>Backup Completo (.zip)</em> inclui mídia compatível ou apenas texto em formato <strong>ZIP sem criptografia</strong>. Os backups locais não são criptografados adicionalmente com senha pelo İcat Defteri.</li><li><strong>Backup no Google Drive (ZIP sem criptografia):</strong> O Usuário pode enviar manualmente à própria conta Google backups com ou sem mídia em formato <strong>ZIP sem criptografia</strong> (sujeito a espaço, cota e rede). Os backups do Google Drive não são criptografados adicionalmente com senha pelo İcat Defteri.</li><li><strong>Restauração:</strong> <em>Mesclar</em> adiciona novos itens; <em>Sobrescrever</em> substitui os dados locais após confirmação.</li></ul>"],["4. Voz, Anexos e Lixeira","<ul><li>O ditado por voz usa Serviços de Fala Android/Google sem gravar áudio bruto.</li><li><em>Gravar Áudio (.m4a)</em> salva na área privada <code>files/recordings/</code>, nunca na pasta pública Música. Se o arquivo faltar, a nota continua legível com aviso.</li><li>Fotos, vídeos, documentos (limite 200 MB/arquivo) e desenhos são copiados de modo independente para <code>files/attachments/</code>: apagar o original na Galeria preserva a cópia na nota, e excluir definitivamente no app não altera o original na Galeria. Compartilhar/PDF gera cópia separada.</li></ul>"],["5. Limitação de Responsabilidade","<p>As limitações aplicam-se apenas na extensão permitida por lei e não afastam direitos irrenunciáveis do consumidor. Defeitos do aparelho, formatação, falta de backup externo ou atraso de lembretes por otimização de bateria fogem ao controle do Desenvolvedor. O App é fornecido «como está»; Google Drive e ditado seguem termos de terceiros. Desconectar a conta Google não apaga backups já salvos no Drive.</p>"],["6. Propriedade Intelectual, Privacidade e Contato","<p>Código, interface e marca pertencem a Ramazan Kocatürk; todo conteúdo criado pelo Usuário (ideias, notas, áudios, arquivos) pertence 100% ao Usuário. Aceitar este Acordo não implica consentimento amplo para permissões opcionais; detalhes sobre dados (incluindo KVKK n.º 6698) constam na Política de Privacidade.<br><strong>E-mail:</strong> <a href=\"mailto:ramazankocaturk@gmail.com\" >ramazankocaturk@gmail.com</a></p>"]]}}};

  function escHtml(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function renderDocForLang(lang) {
    var page = document.body ? document.body.dataset.page : '';
    var data = null;
    if (page === 'guide') data = GUIDE[lang] || GUIDE.tr;
    else if (page === 'privacy') data = (LEGAL[lang] || LEGAL.tr).privacy;
    else if (page === 'terms') data = (LEGAL[lang] || LEGAL.tr).terms;
    if (!data) return;

    var badgeEl = document.getElementById('doc-badge');
    var headEl = document.getElementById('doc-heading');
    var metaEl = document.getElementById('doc-meta');
    var hiEl = document.getElementById('doc-highlight-host');
    var secEl = document.getElementById('doc-sections-host');
    var dToc = document.getElementById('desktop-toc-list');
    var mToc = document.getElementById('mobile-toc-list');

    if (badgeEl) badgeEl.textContent = data.badge || '';
    if (headEl) headEl.textContent = data.title || '';
    if (metaEl) metaEl.textContent = data.meta || '';
    if (hiEl) hiEl.innerHTML = data.highlight ? '<div class="highlight-box">' + data.highlight + '</div>' : '';

    if (secEl) {
      secEl.innerHTML = data.sections.map(function (pair, idx) {
        return '<section id="sec-' + (idx + 1) + '" class="doc-section"><h2>' + escHtml(pair[0]) + '</h2><div class="doc-prose">' + pair[1] + '</div></section>';
      }).join('');
    }
    var tocHtml = data.sections.map(function (pair, idx) {
      return '<li><a href="#sec-' + (idx + 1) + '">' + escHtml(pair[0]) + '</a></li>';
    }).join('');
    if (dToc) dToc.innerHTML = tocHtml;
    if (mToc) mToc.innerHTML = tocHtml;

    var btns = document.querySelectorAll('[data-doc-lang]');
    for (var i = 0; i < btns.length; i++) {
      btns[i].classList.toggle('active', btns[i].getAttribute('data-doc-lang') === lang);
    }
  }

  window.addEventListener('icat:langchange', function (e) {
    if (e && e.detail && e.detail.lang) renderDocForLang(e.detail.lang);
  });

  document.addEventListener('DOMContentLoaded', function () {
    var btns = document.querySelectorAll('[data-doc-lang]');
    for (var i = 0; i < btns.length; i++) {
      btns[i].addEventListener('click', function () {
        var l = this.getAttribute('data-doc-lang');
        if (window.ICAT_SET_LANG) window.ICAT_SET_LANG(l);
        else renderDocForLang(l);
      });
    }
  });
})();
